insert into public.activity_overviews (slug, overview, updated_at) values
  ($s$common2/mini/two_point_distance$s$, $ov$수직선과 좌표평면에서 두 점을 직접 끌어 움직이며 두 점 사이의 거리가 계산되는 과정을 관찰하는 활동. 1차원에서는 좌표의 차의 절댓값으로, 2차원에서는 가로·세로 차이를 두 변으로 하는 직각삼각형과 피타고라스 정리로 거리 공식이 유도됨을 시각적으로 탐구한다. 마지막 탭에서는 좌표평면 위 마을 지도에서 두 장소 사이의 거리를 가로 차이·세로 차이·거리의 제곱을 단계별로 구해 해결하는 배달 게임을 한다.$ov$, now()),
  ($s$common2/mini/internal_division_lab$s$, $ov$수직선 위의 두 점을 끌고 비 m:n 을 슬라이더로 바꾸며 선분 AB를 m:n 으로 내분하는 점 P의 좌표가 (m·x2 + n·x1)/(m+n) 로 정해지는 과정을 시각적으로 탐구하는 활동. 두 번째 탭에서는 내분의 개념을 황금비에 연결해, 막대를 눈대중으로 나눠 황금분할점(약 0.618 지점)을 맞히는 챌린지와, 내분비 m:n 을 피보나치 수로 잡을수록 황금비 φ 에 수렴함을 확인하는 활동을 한다.$ov$, now()),
  ($s$common2/mini/centroid_lab$s$, $ov$삼각형의 무게중심 성질을 내분과 연결해 네 개의 탭에서 조작·시뮬레이션하는 활동. 무게중심이 각 중선을 꼭짓점에서부터 2:1로 내분함을 꼭짓점을 끌며 확인하고(G=(2M+A)/3), 삼각형 내부 점 P에 대해 AP제곱+BP제곱+CP제곱 의 값을 히트맵으로 시각화해 무게중심에서 최소가 됨을 탐색하며, 세 변의 중점으로 만든 중점삼각형(예: A(1,0),B(5,2),C(3,4))의 무게중심이 원래 무게중심과 일치함을 좌표로 확인한다. 마지막 탭에서는 각 변을 같은 비 s로 내분한 삼각형의 무게중심도 원래 삼각형과 항상 일치함을 슬라이더로 일반화해 확인한다.$ov$, now()),
  ($s$common2/mini/block_stacking_lab$s$, $ov$같은 블록 n개를 책상 밖으로 무너지지 않게 최대한 밀 때 빠져나온 길이 L_n=(l/2)(1+1/2+...+1/n)이 됨을 탐구하는 활동. 슬라이더로 블록 개수를 조절해 최적으로 밀린 계단 모양과 L_n을 시뮬레이션하고(맨 위 블록이 책상 밖으로 완전히 나가는 순간 확인), n에 따른 L_n 그래프로 조화급수의 느리지만 무한한(발산) 증가와 원하는 거리에 도달하는 데 필요한 블록 수의 폭발적 증가를 관찰하며, 무게중심이 두 블록의 무게중심을 잇는 선분을 내분한다는 지렛대 원리와 연결하고 퀴즈로 확인한다.$ov$, now()),
  ($s$common2/mini/line_equation_lab$s$, $ov$한 점의 좌표와 기울기가 주어진 직선, 그리고 두 점이 주어진 직선의 방정식을 세 탭으로 탐구하는 활동. ①한 점 + 기울기 — 좌표평면에서 점 A를 끌어 옮기고 기울기 m을 −4~4 사이에서 0.5씩 바꾸면 기울기 삼각형(오른쪽 몇 칸, 위/아래 몇 칸)과 직선이 함께 움직이며, 공식 y−y₁=m(x−x₁) → 좌표를 그대로 넣은 대입식 → 부호를 정리한 식 → y=mx+n 완성식이 네 줄로 동시에 갱신된다. ‘돌려보기’로 기울기를 자동 회전시키고 ‘잔상 남기기’로 여러 기울기의 직선을 겹쳐 보면 m의 값에 관계없이 모든 직선이 항상 점 A를 지남을(x에 x₁을 넣으면 오른쪽이 m×0=0이 되므로) 눈으로 확인하며, ‘y=mx의 평행이동’을 켜면 원점을 지나는 직선을 (x₁, y₁)만큼 옮긴 것임을 보여 준다. 이어 점 A(2,3)·기울기 2(y=2x−1), 점 B(−1,4)·기울기 −3(y=−3x+1), 점 C(4,−2)·기울기 ½(y=½x−4) 세 문제를 점기울기 꼴 빈칸 채우기 → y=mx+n으로 정리하기 2단계로 풀며, 맞히면 미니 그래프에 직선이 그려진다. ②가로선·세로선 — 기울기 슬라이더와 ‘기울기 0’·‘y축에 평행’ 버튼으로 직선을 눕히거나 세우면서, 기울기가 0이면 y−y₁=0(x−x₁) → y=y₁ (x축에 평행)이 되고, y축에 평행한 직선은 가로 변화량이 0이라 (세로 변화)÷(가로 변화)를 정할 수 없어 기울기가 없으므로 점기울기 꼴을 쓸 수 없고 x=x₁로 나타냄을 그림과 식으로 대비한다. x축에 평행한데 x=□로 쓰는 흔한 실수를 짚는 안내와 정리표를 두고, 그래프를 보고 식을 고르거나 조건을 보고 식을 고르는 6문항 퀴즈(y=3, x=−2, 점 (4,−1)의 가로선·세로선, 기울기 0인 직선, y=−x+2)로 확인한다. ③두 점 잇기 — 두 점 A, B를 끌면 x좌표의 차·y좌표의 차가 표시되고 m=(y₂−y₁)/(x₂−x₁) → 점기울기 꼴 → y=mx+n이 단계별로 계산되며, 기준점을 A로 잡든 B로 잡든 정리하면 같은 식이 됨을 나란히 보여 준다. 두 점의 x좌표가 같아지면 기울기를 구할 수 없음과 x=x₁을, 두 점이 겹치면 직선이 하나로 정해지지 않음을 안내한다. 마지막으로 별 잇기 미션 5라운드 — A(1,2)·B(4,8)→y=2x, A(−2,5)·B(2,−3)→y=−2x+1, A(−3,4)·B(2,4)→y=4(기울기 0), A(3,−4)·B(3,2)→x=3(기울기 없음), A(−4,−3)·B(2,3)→y=x+1 — 을 y의 차 → x의 차 → 기울기 → 방정식 순서로 앞 단계를 맞혀야 다음이 열리는 방식으로 풀며, 성공하면 두 별이 직선으로 이어진다. 모든 정답은 계산으로 검산했으며 좌표는 정수 격자 위의 값이다.$ov$, now()),
  ($s$common2/mini/two_lines_relation_lab$s$, $ov$두 직선의 위치 관계(일치·평행·한 점에서 교차·수직)를 판정하는 세 탭 활동. ①두 직선 실험실 — 직선 l과 l''을 각각 표준형 y=mx+n 또는 일반형 ax+by+c=0 중 원하는 형태로 입력하면(형태 전환 시 식이 자동 변환) 두 직선이 좌표평면에 그려지고, 교점과 수직 표시가 함께 나타나며 판정 결과가 배지로 뜬다. 판정 근거는 표준형 관점(m과 m''이 같은가, n과 n''이 같은가, mm''=-1인가)과 일반형 관점(ab''-a''b가 0인가, aa''+bb''=0인가, 계수가 모두 0이 아니면 a/a''·b/b''·c/c'' 비교)을 나란히 보여 준다. 평행·수직·일치·교차 만들기 버튼으로 직선 l''을 즉시 바꿔 가며 조건을 체감할 수 있고, y축에 평행한 직선(x=k)처럼 기울기가 없는 경우와 계수에 0이 있어 비례식을 쓸 수 없는 경우도 곱셈꼴 판정(ab''-a''b, aa''+bb'')으로 안전하게 다룬다. ②위치 관계 퀴즈 — 표준형·일반형·혼합형이 섞인 10문제를 차례로 풀며 네 가지 위치 관계를 4지선다로 고르고, 답을 고르면 두 직선을 그린 그래프와 판정 과정 해설이 함께 나온다(평행 2·수직 4·일치 2·교차 2, x=3과 y=4처럼 세로선과 가로선이 수직인 특수 사례 포함). ③1분 스피드 퀴즈 — 60초 동안 무작위로 생성되는 문제(표준형·일반형 무작위 혼합)를 최대한 많이 맞히는 속도 대결로, 오답이면 남은 시간이 3초 줄어들어 찍기를 막는다. 종료하면 점수가 기존 도전 모드 랭킹(submit_activity_score RPC)에 자동 기록되고, 학생별 최고 점수를 모은 순위표(Top 20, 메달·이름·학급·최고 점수, 내 행 강조)가 활동 아래에 표시된다. 이 기기의 최고 기록도 함께 보여 준다. 퀴즈 10문제의 정답과 무작위 생성기는 모두 계산으로 검산했다.$ov$, now()),
  ($s$common2/mini/point_line_distance_lab$s$, $ov$점과 직선 사이의 거리를 세 탭으로 탐구하는 활동. ①왜 수선일까? — 좌표평면에서 점 A와 직선 위의 점 P를 각각 끌어 옮기고 직선의 기울기·y절편을 슬라이더로 바꾸면 선분 AP의 길이가 실시간으로 갱신되며, P의 x좌표에 따른 AP 길이 곡선이 아래 그래프로 함께 그려져 수선의 발 H에서 최솟값을 가짐을 눈으로 확인한다. ‘가장 짧은 곳으로’ 버튼은 P를 H까지 애니메이션으로 이동시키고, ‘여러 점까지 한꺼번에’는 직선 위 여러 점까지의 선분을 동시에 그려 비교하게 하며, H에는 직각 표시가 나타난다. 이어 d=|ax₁+by₁+c|/√(a²+b²) 공식에 현재 값을 대입한 식과 계산 결과를 보여 주어 자로 잰 최소 길이와 같음을 확인시킨다. ②거리 공식 연습 — 일반형(3x+4y−5=0과 점 (2,3) → 13/5, 원점과 3x+4y−10=0 → 2)과 표준형(y=2x+3과 점 (1,−2) → 7√5/5, y=−x+2와 점 (5,−1) → √2) 네 문제를 단계별 빈칸으로 푼다. 표준형 문제는 먼저 ax+by+c=0 꼴로 고치는 객관식 단계를 거치고, 이어 분자 |ax₁+by₁+c|와 분모 a²+b²을 입력한 뒤 유리화한 최종 거리를 고르며, 맞히면 옆 그래프에 수선과 직각 표시가 그려진다. ③평행한 두 직선 — 교과서와 같은 2x+y+1=0, 2x+y−4=0을 포함한 세 문제를, 두 직선이 평행한 까닭 고르기 → l₁ 위의 점을 자유롭게 하나 고르고 y좌표 구하기 → 그 점과 l₂ 사이의 거리 분자·분모 구하기 → 최종 거리 고르기 순서로 푼다(표준형 문제는 정수 계수 일반형으로 고치는 단계가 앞에 붙는다). 옆의 시뮬레이터에서 l₁ 위의 점 P를 끌어도 l₂까지의 거리가 변하지 않음을, ‘여러 곳에서 재보기’로 여러 수선을 동시에 그려 확인하고, ax₀+by₀=−c₁ 이므로 |ax₀+by₀+c₂|=|c₂−c₁| 이 되어 d=|c₁−c₂|/√(a²+b²) 로 정리됨을 마무리 카드로 보여 준다. 모든 문제의 정답과 무리수 유리화 표기는 계산으로 검산했다.$ov$, now()),
  ($s$common2/mini/parallel_perp_lab$s$, $ov$교과서의 공학 도구 활동(한 점 C를 지나고 직선 AB에 평행한 직선과 수직인 직선 구하기)을 세 탭으로 옮기고 확장한 활동. ①공학 도구 실험실 — 세 점 A, B, C를 모두 끌 수 있고, 직선 AB(빨강)와 점 C를 지나는 평행선(파랑)·수직선(보라)이 실시간으로 다시 그려지며, 지오지브라의 대수 창처럼 A·B·C의 좌표와 세 직선의 방정식이 목록으로 표시된다(평행선·수직선은 켜고 끌 수 있음). 교과서 예시 A(−2,1)·B(2,3)·C(1,−1)을 한 번에 불러오면 y=½x+2, y=½x−3/2, y=−2x+1 이 그대로 재현된다. 기울기 관계 카드에서 평행선은 기울기가 같고 수직선은 음의 역수이며 m×m′=−1 임을 확인하고, 손으로 구하는 과정(기울기 → 점기울기 꼴 → 정리)도 3단계 카드로 보여 준다. AB가 세로선·가로선이어서 기울기가 없거나 0인 경우, A와 B가 겹쳐 직선이 정해지지 않는 경우까지 안내한다. ②교과서 활동·결과 모으기 — A(−3,6), B(1,−4)를 고정하고 학생이 점 C를 마음대로 골라, AB의 기울기(분자·분모 입력) → 평행선의 기울기 → 수직선의 기울기를 단계별 빈칸으로 구한 뒤 완성된 두 방정식을 확인한다. ‘내 결과 모으기’로 서로 다른 C를 최대 6개까지 쌓으면 각각의 평행선·수직선이 한 화면에 함께 그려지고 표로 정리되어, 교과서의 ‘친구들과 비교해 보자’를 재현한다. 기울기는 모두 −5/2와 2/5로 같고 상수항만 달라진다는 발견 카드로 마무리한다. ③넓이 미션 — 같은 A, B에서 점 C를 끌어 삼각형 ABC의 넓이를 6·10·15로 정확히 맞추는 미션. 점 C에서 AB에 내린 수선의 발과 거리 d가 함께 표시되고, 넓이를 ½×AB×d(점과 직선 사이의 거리 이용)와 신발끈 공식 두 가지로 계산해 같은 값이 나옴을 보여 준다(A(−3,6), B(1,−4)에서 AB는 5x+2y+3=0 이라 넓이가 |5Cx+2Cy+3| 로 정수가 된다). ‘자취 보기’를 켜면 같은 넓이를 주는 점 C들이 AB에 평행한 두 직선 위에 놓임을 확인할 수 있다. 교과서 예시 값, 평행·수직 판정, 수선의 발과 넓이의 일치는 무작위 3,000회를 포함해 계산으로 검산했다.$ov$, now()),
  ($s$common2/mini/circle_equation_lab$s$, $ov$원의 방정식 표준형 (x−a)²+(y−b)²=r² 을 세 탭으로 탐구하는 활동. ①원의 방정식이 태어나는 순간 — 교실 와이파이(중심 원점, 반경 6), 배달 가능 지역(가게 (3,1), 반경 5), 등대 불빛((−2,2), 반경 6), 강아지 목줄((2,−3), 반경 4), 기지국 통화권((−3,−3), 반경 5) 다섯 가지 상황을 고르면 좌표평면에 그 원이 그려지고, 색깔 점을 끌어 옮기면 (x−a)²+(y−b)² 값과 r² 을 나란히 계산해 ''신호가 잡혀요/배달 가능/불빛이 보여요'' 처럼 상황에 맞는 말로 내부·원 위·외부를 판정한다. 중심에서 점까지의 가로 |x−a|·세로 |y−b| 로 이루어진 직각삼각형이 함께 그려져 왜 제곱의 합이 나오는지 보이고, 상황마다 세 지점(내부·원 위·외부 각 하나)의 위치를 먼저 예상해 맞히는 퀴즈가 붙는다. 이어 원의 뜻 → CP = r → √{(x−a)²+(y−b)²} = r → 양변 제곱 네 단계 카드로 표준형을 유도하고, 중심이 원점이면 x²+y²=r² 이 됨을 함께 제시한다. ②중심·반지름 ⇄ 방정식 — 중심과 반지름을 보고 방정식을 고르는 문제와, 방정식을 보고 중심의 좌표를 입력하고 반지름을 고르는 문제를 섞어 8문제를 풀며, 맞히면 그 원이 반지름 표시와 함께 그려진다. (x+1)²=(x−(−1))² 같은 부호 함정과 오른쪽 값이 r 이 아니라 r² 이라는 점, r²=12 → r=2√3 처럼 근호를 간단히 하는 경우를 다룬다. ③지름의 양 끝점 — 지름의 두 끝점 A, B 를 끌면 중심(중점)·지름²·반지름²·원의 방정식이 실시간으로 계산되고, 보너스로 원 위의 점 P 를 돌려 ∠APB 가 언제나 90°임(지름에 대한 원주각)을 확인할 수 있다. 이어 A(1,3)·B(5,−1) → (x−3)²+(y−1)²=8, A(−2,4)·B(4,−4) → (x−1)²+y²=25, A(−1,2)·B(5,2) → (x−2)²+(y−2)²=9, A(2,−3)·B(−2,5) → x²+(y−1)²=20 네 문제를 중점 → 지름² → 반지름² → 방정식 순서의 빈칸으로 푼다. 상황 설정값은 활동을 위해 정한 가상의 값이며, 모든 문제의 정답·근호 정리·판정 결과는 계산으로 검산했다.$ov$, now()),
  ($s$common2/mini/circle_general_form_lab$s$, $ov$원의 방정식의 표준형 (x−a)²+(y−b)²=r² 과 일반형 x²+y²+Ax+By+C=0 을 세 탭으로 다루는 활동. ①분류 퀴즈 — 10개의 식을 하나씩 보여 주고 표준형·일반형·원이 아님 중에서 고르게 한다. 답을 고르면 그 식이 나타내는 원이 그려지고 근거가 해설로 나온다. 원이 되지 못하는 네 가지 경우를 모두 담았다: A²+B²−4C<0 이라 만족하는 점이 없는 경우(x²+y²+2x−4y+9=0), A²+B²−4C=0 이라 점 하나뿐인 경우(x²+y²−6x+2y+10=0), x²과 y²의 계수가 다른 경우(x²+2y²−4x=0), xy 항이 있는 경우(x²+y²+xy−2=0). 계수가 2로 같아 양변을 나누면 원이 되는 2x²+2y²−4x+8y−6=0 같은 함정도 포함한다. ②표준형 ⇄ 일반형 — 중심 a·b 와 반지름 r 을 슬라이더로 움직이면 같은 원의 표준형과 일반형이 동시에 갱신되고 A=−2a, B=−2b, C=a²+b²−r² 의 관계가 함께 표시되는 변환기를 먼저 두었다. 이어 표준형을 전개해 A·B·C 를 구하는 문제 3개(중심 (2,−3) r=4, (−1,2) r=3, (0,5) r²=7)와 일반형을 완전제곱해 중심·r² 을 구하는 문제 3개(x²+y²−6x+8y+9=0, x²+y²+4x−2y−4=0, x²+y²−2x+6y+6=0)를 빈칸으로 풀며, 맞히면 그 원이 그려진다. ③세 점을 지나는 원 — O(0,0), P(0,2), Q(4,−2) 를 지나는 원을 두 가지 방법으로 구한다. 좌표평면의 분홍 점 C 를 끌면 세 점까지의 거리의 제곱이 실시간으로 표시되어 세 값이 같아지는 자리를 직접 찾을 수 있고, 힌트를 켜면 두 수직이등분선이 그려져 그 교점이 중심임을 보여 준다. 방법 ①은 CO=CP=CQ 에서 얻은 두 조건식으로 중심과 r² 을 구하고, 방법 ②는 일반형에 세 점을 차례로 대입해 C=0 → B=−2 → A=−6 을 구하며, 두 방법 모두 (x−3)²+(y−1)²=10 = x²+y²−6x−2y=0 이라는 같은 답에 이른다는 것을 나란히 확인한다. 원점을 지나지 않는 도전 문제(세 점 (1,1), (5,1), (1,5) → (x−3)²+(y−3)²=8)도 준비해, 이때는 세 식을 서로 빼서 A, B 를 먼저 구하는 방법을 다룬다. 분류 카드의 판별값, 변환 문제의 왕복 일치(무작위 5,000회), 세 점이 실제로 원 위에 있고 수직이등분선의 교점이 중심임은 모두 계산으로 검산했다.$ov$, now()),
  ($s$common2/mini/tangent_axis_circle_lab$s$, $ov$좌표축에 접하는 원을 세 탭으로 탐구하는 활동. 사분면별 여덟 가지 식을 외우게 하는 대신 ''중심에서 그 직선까지의 거리 = 반지름''이라는 한 줄을 조작으로 체득하게 구성했다. ①축에 딱 붙이기 — 원의 중심을 끌고 반지름 슬라이더를 움직이면 중심에서 x축·y축까지의 거리 |b|, |a| 가 선분과 함께 표시되고, 각 축에 대해 만나지 않음(거리>r)·접함(=r)·두 점에서 만남(<r) 상태가 실시간으로 판정된다. 접하는 순간 접점이 찍히고 원의 색이 바뀌며, x축에만 접하기·y축에만 접하기·두 축에 모두 접하기 세 미션을 별로 모은다. 아래에 |b|=r ⇔ x축에 접함, |a|=r ⇔ y축에 접함이라는 핵심 한 줄을 정리한다. ②사분면 갤러리 — x축에 접함·y축에 접함·두 축에 모두 접함 중 하나를 고르고 a(또는 b)와 r 슬라이더를 움직이면 네 사분면의 원이 동시에 움직이며, 각 칸에 기호식((x−a)²+(y−r)²=r² 등)과 현재 수치식이 함께 표시되어 열두 가지 형태가 한눈에 비교된다. 중심에서 각 축까지의 거리와 접점이 미니 그래프마다 그려져 부호가 왜 그렇게 되는지 그림으로 보이며, ''중심의 좌표를 표준형에 그대로 넣고 접하는 축 쪽 좌표만 r 로 바꾸면 끝''이라는 규칙 카드로 정리한다. ③조건에서 원 찾기 — 원을 정하는 데 필요한 점의 개수가 미지수의 개수(a, b, r 중 몇 개가 남는지)로 정해짐을 카드로 보여 준 뒤, 두 축에 모두 접하고 점 (2,1)을 지나는 원(답이 (x−1)²+(y−1)²=1 과 (x−5)²+(y−5)²=25 두 개), x축에 접하고 두 점 (1,1)·(7,1)을 지나는 원((x−4)²+(y−5)²=25), y축에 접하고 두 점 (1,1)·(1,7)을 지나는 원((x−5)²+(y−4)²=25) 세 문제를 단계별 빈칸으로 푼다. 뒤의 두 문제는 x와 y를 맞바꾼 데칼코마니라는 점도 짚는다. 열두 가지 기호식이 실제로 접하는 조건을 만족하는지, 세 문제의 해가 그것뿐인지는 완전탐색을 포함해 계산으로 검산했다.$ov$, now()),
  ($s$common2/mini/apollonius_circle_lab$s$, $ov$두 점에서의 거리 조건이 만드는 자취를 세 탭으로 탐구하는 활동. ①비가 일정한 점 찾기 — 두 점 A, B 를 끌어 놓고 비를 1:1부터 4:3까지 고른 뒤 점 P 를 직접 끌어 PA:PB 가 그 비가 되는 자리를 찾으면 주황 점이 하나씩 남는다. 점을 여러 개 모은 뒤 ''자취 보기''를 누르면 그 점들이 원 위에 놓여 있었음이 드러나고, 선분 AB 를 m:n 으로 내분한 점 C 와 외분한 점 D 가 그 원의 지름의 양 끝임을 함께 보여 준다(아폴로니오스의 원). 오른쪽에는 n·PA = m·PB → 양변 제곱 → 좌표 대입 → 정수 계수로 정리 → 표준형까지 식이 단계별로 갱신되어, x²과 y²의 계수가 같고 xy 항이 없으므로 원이 된다는 것을 확인한다. 비가 1:1 이면 x²+y² 의 계수 n²−m² 이 0 이 되어 이차항이 사라지고 자취가 선분 AB 의 수직이등분선(직선)이 되는 것도 직접 보게 되며, 비가 1 에 가까울수록 원이 커진다는 관찰을 정리한다. 원이 커져도 잘리지 않도록 좌표평면의 축척이 자동으로 조정된다. ②거리 조건 3형제 — 같은 두 점에 대해 PA:PB = m:n(원), PA²+PB² = k(원, 중심은 AB 의 중점), PA²−PB² = k(직선, AB 에 수직) 세 조건을 슬라이더로 바꿔 가며 자취를 비교한다. 제곱의 합에서는 k 가 작아지면 반지름이 0 이 되어 점 하나가 되고 더 작아지면 그런 점이 아예 없어지는 것을, 제곱의 차에서는 x²과 y²이 서로 지워져 일차식만 남는 까닭을 함께 보여 준다. ③두 원이 만나는 곳 — 두 원의 중심을 끌고 반지름을 바꾸며 다섯 가지 위치 관계(떨어짐·외접·두 점에서 만남·내접·포함)를 판정하고, ''빼 보기'' 버튼을 누르면 두 일반형의 차에서 x², y² 이 사라져 일차식만 남는 것과 그 직선이 두 교점을 정확히 지나는 것(공통현)을 확인한다. 아폴로니오스 원의 성질(비·내분점·외분점·수직이등분선), 세 가지 자취, 두 원의 교점과 근축은 각각 무작위 3,000회를 포함해 계산으로 검산했다.$ov$, now()),
  ($s$common2/mini/circle_line_relation_lab$s$, $ov$원과 직선의 위치 관계를 네 탭으로 다루는 활동. ①직선을 밀어 보자 — 좌표평면을 끌면 직선이 따라 움직이고, 기울기·y절편·반지름 슬라이더와 자동 재생(직선 지나가기) 버튼으로 직선이 원을 가로지르고 스치고 비껴가는 과정을 연속으로 볼 수 있다. 교점의 개수(2·1·0)와 위치 관계가 실시간으로 판정되어 직선의 색이 분홍·초록·주황으로 바뀌고, 중심에서 직선에 내린 수선과 거리 d가 직각 표시와 함께 그려진다. 세 가지 위치 관계를 모두 만들어 별을 모으는 미션이 있고, 아래에는 기울기가 같은 세 직선을 한 좌표평면에 겹쳐 그려 달라지는 것이 중심에서 직선까지의 거리 하나뿐임을 보여 준다(교과서 그림 재현 — 반지름 3, 기울기 1, y절편 1.5 / 3√2 / 7). ②연립해서 판별식 — 원 x²+y²=r² 과 직선 y=mx+n 을 연립해 (m²+1)x²+2mnx+n²−r²=0 으로 정리한 뒤 판별식으로 판정하는 6문제. 학생이 이차방정식의 세 계수를 빈칸에 넣고 D/4 를 구한 다음 위치 관계를 고르면 그래프와 풀이가 열리며, 두 근이 곧 교점의 x좌표임을 교점 좌표와 함께 확인한다(x²+y²=5 와 y=x+1 → D/4=9, 교점 (1,2)·(−2,−1) / x²+y²=10 과 y=3x+10 → D/4=0, 접점 (−3,1) / x²+y²=4 와 y=x+4 → D/4=−8 / x²+y²=25 와 y=2x−5 → D/4=100, 교점 (0,−5)·(4,3) / x²+y²=8 과 y=x+4 → D/4=0, 접점 (−2,2) / x²+y²=9 와 y=−x+3 → D/4=9, 교점 (0,3)·(3,0)). ③거리로 판정 — 원의 중심과 직선을 각각 끌 수 있는 실험실에서 d 와 r 을 막대 두 개로 나란히 견주어 어느 쪽이 긴지 눈으로 보게 하고, D/4=(m²+1)(r²−d²) 이므로 m²+1 이 항상 양수여서 판별식 판정과 거리 판정이 언제나 같은 답을 준다는 것을 정리한다. 이어 중심이 원점이 아닌 원까지 포함한 6문제를 거리 공식의 분자와 분모 빈칸을 채워 풀며, 근호가 있는 수끼리 비교가 어려울 때는 양변을 제곱해 d² 과 r² 을 견주라는 안내를 붙였다. ④현의 길이 — 직선을 끌면 현 AB, 수선의 발 H, 반현 AH, 거리 d 가 실시간으로 갱신되고 d²+AH²=r² 이 수치로 확인된다. 현의 길이를 6·8·지름으로 정확히 맞추는 미션과, d 가 0에서 r 까지 갈 때 현의 길이가 지름 2r 에서 0 으로 줄어드는 관계 그래프를 함께 두었다. 문제는 d² 을 구하고 → 피타고라스의 정리로 r²−d² 을 구하고 → 현의 길이를 고르는 3단계로 4문제(x²+y²=25 와 3x+4y−15=0 → 8, (x−2)²+(y−1)²=25 와 3x+4y−30=0 → 6, x²+y²=9 와 x−2=0 → 2√5, 직선이 중심을 지나 d=0 이 되는 경우 → 지름 6)를 풀고, 현의 길이가 8인 직선 y=k 를 거꾸로 찾는 도전 문제(k=±3)로 마무리한다. 교과서 슬라이드에는 현의 길이가 AB=2AH=√(r²−d²) 로 적혀 있으나 계수 2가 빠진 오기이므로(바른 식은 AB=2√(r²−d²)) H 가 현의 중점임을 근거로 활동 안에서 바로잡아 안내한다. 판별식 판정과 거리 판정이 언제나 일치하는지, 모든 문제의 교점·거리·현의 길이가 맞는지는 무작위 5,000회를 포함해 계산으로 검산했고, 활동에서 만들어지는 수식은 전부 렌더 테스트를 거쳤다.$ov$, now()),
  ($s$common2/mini/circle_tangent_line_lab$s$, $ov$원의 접선의 방정식을 접선을 정하는 단서에 따라 세 탭으로 나누어 다루는 활동. 세 탭 모두 중심이 원점인 원에서 식을 만든 뒤 중심이 (a, b) 인 원으로 넓히는 순서를 따르며, 실험실에서 원의 중심을 끌어 옮기면 공식 표시가 원점용에서 평행이동용으로 자동으로 바뀐다. ①기울기를 알 때 — 기울기 슬라이더(자동 훑기 버튼 포함)를 움직이면 같은 기울기의 두 접선이 위쪽·아래쪽에 동시에 그려지고, 두 접점과 반지름, 접점에서의 직각 표시가 함께 나타나 접선이 언제나 2개임을 눈으로 확인한다. 오른쪽에는 y = mx ± r√(m²+1) (중심이 (a,b) 이면 y − b = m(x − a) ± r√(m²+1))과 현재 값이 실시간으로 표시된다. 문제는 m²+1 → r√(m²+1) → 두 y절편의 3단계 빈칸으로 6개(x²+y²=2 와 m=1 → y = x ± 2, x²+y²=5 와 m=2 → y = 2x ± 5, x²+y²=10 과 m=−3 → y = −3x ± 10, (x−2)²+(y+1)²=8 과 m=1 → y=x+1·y=x−7, (x+1)²+(y−3)²=2 와 m=1 → y=x+6·y=x+2, (x−3)²+(y−1)²=5 와 m=2 → y=2x·y=2x−10). ②접점을 알 때 — 접점 P 를 원 위에서 직접 끌면 접선과 반지름이 따라 움직이고 (x₁−a)(x−a)+(y₁−b)(y−b)=r² 이 실시간으로 갱신된다. 위·아래·좌·우 끝으로 보내는 버튼을 두어 x₁=a 또는 y₁=b 인 경우(가로선·세로선 접선)에도 같은 공식이 그대로 성립함을 확인하게 했고, 반지름과 접선이 수직임 → 접선의 기울기가 −x₁/y₁ → 정리하면 x₁x+y₁y=x₁²+y₁²=r² 로 이어지는 유도를 4줄 카드로 함께 보여 준다. 문제는 접점이 원 위에 있는지 확인 → 공식에 넣을 두 계수의 2단계 빈칸으로 6개(x²+y²=25 와 P(3,4) → 3x+4y=25, x²+y²=13 과 P(2,−3) → 2x−3y=13, x²+y²=9 와 P(0,−3) → y=−3, (x−1)²+(y−2)²=25 와 P(4,6) → 3x+4y=36, (x+2)²+(y−1)²=13 과 P(0,4) → 2x+3y=12, (x−3)²+(y+1)²=10 과 P(4,2) → x+3y=10). ③원 밖의 점에서 — 점 A 를 끌면 두 접선과 두 접점이 실시간으로 그려지고, 접선의 개수 배지가 원 밖이면 2·원 위면 1·원 안이면 0 으로 바뀌어 왜 원 밖의 점에서는 항상 2개인지 몸으로 알게 한다. 중심에서 A 까지의 거리 d 와 두 접선의 길이 √(d²−r²) 가 함께 표시되고, ''두 접점을 잇는 직선 보기'' 버튼을 누르면 A 를 접선의 식에 대입해 만든 바로 그 일차식이 두 접점을 지나는 직선이라는 숨은 성질이 드러난다. 접선을 찾는 5단계 순서를 카드로 정리한 뒤, A 를 대입한 일차식의 두 계수 → 연립해서 얻은 이차방정식의 두 근(접점의 x좌표) 의 2단계 빈칸으로 4문제를 푼다(x²+y²=5 와 A(3,1) → 접점 (1,2)·(2,−1), 접선 x+2y=5·2x−y=5 / x²+y²=25 와 A(7,1) → 접점 (3,4)·(4,−3), 접선 3x+4y=25·4x−3y=25 / (x−1)²+(y−2)²=5 와 A(4,3) → 접점 (2,4)·(3,1), 접선 x+2y=10·2x−y=5 / (x+2)²+(y−1)²=10 과 A(2,3) → 접점 (−1,4)·(1,0), 접선 x+3y=11·3x−y=3). 중심이 원점이 아닌 문제에서는 X = x−a, Y = y−b 로 옮겨 원점 문제로 바꾼 뒤 되돌리는 방법을 안내한다. 교과서 슬라이드에는 접점이 만족하는 이차식이 x₁²+y₂²=r² 로 인쇄되어 있으나 같은 접점의 좌표이므로 x₁²+y₁²=r² 가 맞아, 활동 안에서 바로잡아 안내한다. 모든 문제의 접선이 실제로 원에 접하는지(중심까지의 거리 = 반지름), 접점이 원 위이자 접선 위이며 수선의 발과 일치하는지, 원 밖의 점 문제에서 두 접선이 모두 그 점을 지나고 접선의 길이가 √(d²−r²) 로 같은지, 접점의 좌표가 정수인지를 전수 검산했고, 세 공식은 무작위 4,000회로 실제 접함을 확인했다. 활동에서 만들어지는 수식은 전부 렌더 테스트를 거쳤다.$ov$, now()),
  ($s$common2/mini/translation_lab$s$, $ov$평행이동을 세 탭으로 다루는 활동. 도형을 식으로 붙잡는 법을 먼저 익힌 뒤 점과 도형을 옮기고, 마지막에 식의 부호가 반대로 들어가는 까닭까지 이른다. ①모든 도형을 식으로 — 여덟 가지 도형(직선 y=x+1, 포물선 y=x²−2, 절댓값 그래프 y=|x|−1, 위쪽 반원 y=√(9−x²), 원 x²+y²=9, 세로 직선 x=2, 누운 포물선 x=y²−3, X자 두 직선 x²=y²)을 하나씩 고른 뒤 빨간 세로선을 좌우로 끌어 도형과 몇 점에서 만나는지 직접 세어 본다. 교점의 개수와 ''지금까지 본 최대 개수''가 실시간으로 표시되고, 두 점 이상에서 만나는 순간이 있으면 y=f(x) 꼴로 쓸 수 없다는 것을 몸으로 알게 한 뒤 O/X 를 판정한다. 세로 직선에서는 교점이 무한히 많다는 특수한 경우도 다룬다. 판정을 맞히면 그 도형의 y=f(x) 꼴(있을 때만)과 f(x,y)=0 꼴, 판정 근거가 함께 열리고, 아래 분류표에 결과가 쌓여 여덟 개 모두 f(x,y)=0 은 ⭕ 이지만 y=f(x) 는 넷만 ⭕ 라는 결론에 이른다. ②점 옮기기 — 점 P 를 끌고 a, b 슬라이더를 움직이면 P′ 로 향하는 분홍 화살표와 가로 a·세로 b 의 직각삼각형이 그려지고, a와 b의 부호가 각각 오른쪽·왼쪽, 위쪽·아래쪽 중 어느 뜻인지 카드로 표시된다. ''삼각형도 함께 옮겨 보기'' 를 켜면 세 꼭짓점이 모두 같은 만큼 움직여 도형 전체가 옮겨지는 모습을 보여 주어 탭③으로 이어 준다. 미션은 세 유형 8문제 — 처음 점과 이동량으로 옮긴 점을 찾기, 처음 점과 옮긴 점으로 이동량을 찾기, 옮긴 점과 이동량으로 처음 점을 되찾기. 특히 되찾기 유형에서는 a, b 를 빼야 한다는 점을 짚어 도형의 식에 x−a 가 들어가는 까닭과 연결한다. 정답 전에는 모르는 점이 그림에 나타나지 않아 좌표를 눈으로 읽어 맞힐 수 없게 했다. ③도형 겹치기 퍼즐 — 원본(연한 점선)·목표(굵은 회색 점선)·현재 도형(색)이 한 좌표평면에 겹쳐 그려지고, a·b 슬라이더로 목표에 정확히 겹치면 반짝이며 방정식 4지선다가 열린다. 선택지에는 부호를 반대로 쓴 함정이 들어 있다. 다섯 라운드는 원 x²+y²=4 를 (3,2) 만큼(→ (x−3)²+(y−2)²=4), 포물선 y=x² 를 (−2,1) 만큼(→ y=(x+2)²+1), 직선 y=2x 를 (1,−3) 만큼(→ y=2x−5), 절댓값 그래프 y=|x| 를 (2,−1) 만큼(→ y=|x−2|−1), 원 (x−1)²+y²=1 을 (−3,3) 만큼(→ (x+2)²+(y−3)²=1) 옮기는 문제다. 슬라이더를 움직이는 동안 정리된 방정식이 계속 갱신되어 부호의 움직임을 눈으로 좇을 수 있다. 아래에는 옮긴 도형 위의 점 P′(x′,y′) 의 원래 자리가 (x′−a, y′−b) 이고 그 점이 원래 도형 위에 있으므로 f(x−a, y−b)=0 이 된다는 4단계 유도와, 점의 평행이동(+a, +b)과 도형의 평행이동(−a, −b)을 나란히 놓은 비교 카드, 그리고 원의 표준형이 바로 이 이야기였다는 연결 카드를 두었다. 여덟 도형의 세로선 교점이 실제 식을 만족하는지와 최대 교점 수로 매긴 함수 판정이 맞는지, 그려지는 곡선의 모든 표본점이 식을 만족하는지, 점 문제 8개의 이동과 되돌리기, 퍼즐 5라운드의 정답 선택지가 이동한 방정식과 일치하고 이동량 0일 때 원본과 같아지는지를 전수 검산했고, f(x−a, y−b)=0 항등식은 무작위 5,000회로 확인했다. 활동에서 만들어지는 수식 914개는 전부 렌더 테스트를 거쳤다.$ov$, now()),
  ($s$common2/mini/reflection_lab$s$, $ov$대칭이동을 세 탭으로 다루는 활동. 대칭의 조건을 손으로 맞춰 본 뒤 좌표와 식으로 넘어가도록 구성했다. ①점대칭·선대칭 — 여섯 라운드에서 대칭이동한 점 P′ 를 학생이 직접 끌어다 놓는다. 격자에 붙어 움직이므로 정답 자리에 정확히 놓을 수 있고, 점대칭에서는 ''세 점 P, O, P′ 이 한 직선 위'' 와 ''OP = OP′'', 선대칭에서는 ''l 과 PP′ 이 수직'' 과 ''PP′ 의 중점이 l 위'' 두 조건이 실시간으로 체크되어 초록으로 켜진다. 선분에는 같은 길이를 뜻하는 빗금과 직각 표시가 교과서 그림처럼 그려지고, OP·OP′ (또는 MP·MP′) 의 길이가 수치로 함께 표시된다. P 도 끌 수 있어 자리를 바꿔 가며 여러 번 확인할 수 있고, ''자동 거울''을 켜면 P′ 가 정답 자리를 따라다녀 규칙을 먼저 관찰할 수 있다. 라운드는 원점에 대한 점대칭, 점 (1,−1) 에 대한 점대칭, x축·y축·직선 y=x·직선 y=x+2 에 대한 선대칭 여섯 가지다. ②점 뒤집기 게임 — 먼저 실험실에서 점 P 를 끌면 x축 대칭·y축 대칭·원점 대칭 세 점이 동시에 따라 움직이며 보조선과 등호 빗금이 교과서 그림을 재현하고, (x,−y)·(−x,y)·(−x,−y) 세 규칙이 실시간 좌표와 함께 표시된다. 이어 다섯 판의 버튼 게임 — 세 대칭 버튼을 눌러 별 모양 목표 좌표에 도착하되 판마다 특정 버튼이 잠긴다. 원점 버튼을 잠근 판에서는 x축 대칭과 y축 대칭을 이어 해야 하고, y축 버튼이나 x축 버튼을 잠근 판도 두 번이면 갈 수 있으며, 마지막 판은 같은 버튼을 두 번 눌러 제자리로 돌아오는 것이 목표다. 누른 순서가 좌표 변화와 함께 기록되고 최소 횟수와 비교해 주며, 서로 다른 두 대칭을 이어 하면 나머지 하나가 된다는 것과 같은 대칭을 두 번 하면 제자리가 된다는 것을 판마다 짚어 준다. ③도형 뒤집기 — 여섯 도형(원 x²+y²=9, 포물선 y=x²−2, 삼차곡선 y=x³/8−x, 누운 포물선 y²=x+3, 직선 y=x+1, 쌍곡선 xy=4)을 골라 세 대칭 버튼을 누르면 원본(회색 점선) 위에 대칭이동한 도형이 겹쳐 그려지고 방정식이 실시간으로 바뀐다. 버튼을 이어 누르면 대칭이 합성되어 x축 다음 y축이 원점 대칭이 되는 것을 도형에서도 확인할 수 있다. 원본과 완전히 겹치면 초록으로 바뀌며 ''자기대칭 도감''의 해당 칸이 ⭕ 또는 ❌ 로 채워져, 원은 세 대칭 모두·포물선은 y축만·삼차곡선과 쌍곡선은 원점만·누운 포물선은 x축만·직선은 어느 것도 아님을 스스로 발견하게 된다(18칸 완성이 목표). 이어 f(x,−y)=0 · f(−x,y)=0 · f(−x,−y)=0 세 규칙 카드와 함께 방정식 6문제를 4지선다로 푼다((x−2)²+(y−1)²=4 의 x축·원점 대칭, y=2x−3 의 y축 대칭, y=(x−1)²+2 의 x축 대칭, 3x−2y+6=0 의 원점 대칭, x²+y²−4x+2y=0 의 y축 대칭). 선택지에는 바꾸지 않아도 되는 자리까지 바꾼 함정이 들어 있다. 평행이동과 달리 점과 도형의 계산 방법이 똑같다는 점을 마무리로 강조한다. 여섯 라운드의 대칭점이 정수 격자 169점 모두에서 정수로 떨어지는지와 중점·수직·거리 조건을 만족하는지, 클라인 사원군 합성표가 좌표 변환과 일치하는지, 게임 다섯 판의 최소 횟수가 너비 우선 탐색 결과와 같은지, 여섯 도형의 곡선 표본점이 모두 식을 만족하고 자기대칭 판정이 실제 변환 결과와 앞뒤가 맞는지, 퀴즈 여섯 문제의 정답이 무작위 4,000점 대입으로 성립하는지를 전수 검산했고, 대칭이동의 성질은 무작위 3,000회로 확인했다. 활동에서 만들어지는 수식은 전부 렌더 테스트를 거쳤다.$ov$, now()),
  ($s$common2/mini/line_yx_reflection_lab$s$, $ov$직선 y = x 에 대한 대칭이동을 세 탭으로 다루고, 마지막에 중단원 전체(평행이동과 네 가지 대칭이동)를 게임으로 정리하는 활동. ①점 뒤집기 — 점 P 를 끌면 대각선 거울 y = x 에 비친 P′ 이 따라 움직이고, PP′ 이 y = x 와 수직임을 보이는 직각 표시와 중점 M 까지의 거리가 같음을 뜻하는 빗금이 함께 그려진다. 좌표 카드가 (x, y) → (y, x) 로 자리를 바꾸는 모습을 크게 보여 주고, y = x 위의 점은 제자리라는 것도 확인할 수 있다. 옆에는 ㉠ 수직 조건에서 x′+y′ = x+y, ㉡ 중점 조건에서 x′−y′ = −x+y 를 얻어 연립하면 x′ = y, y′ = x 가 되는 교과서의 유도를 3단 카드로 정리했다. 이어 좌표 카드 여덟 장(네 쌍)에서 서로 y = x 대칭인 짝을 찾는 짝 맞추기 게임을 둔다. 두 장을 고르면 짝인지 판정되고 맞힌 쌍은 좌표평면에서 초록 선으로 이어지며, 시도 횟수가 기록된다. 카드는 (3,1)·(1,3), (−2,4)·(4,−2), (5,0)·(0,5), (−3,−1)·(−1,−3) 네 쌍이며 짝이 서로 떨어지도록 미리 섞어 두었다. ②도형 그려내기 — 여섯 도형(포물선 y=x²−2, 직선 y=2x+1, 원 (x−3)²+(y−1)²=4, 절댓값 그래프 y=|x|−2, 원 x²+y²=9, 쌍곡선 xy=4) 위에서 슬라이더로 점을 움직이면 그 점의 y=x 대칭점이 초록 점으로 하나씩 쌓인다. 여덟 개 이상 모으면 ''완성된 도형 보기'' 가 열려 점들이 놓여 있던 곡선의 정체가 드러나고, 원본 → x 와 y 를 맞바꾼 식 → 정리한 식이 나란히 표시된다. 원 x²+y²=9 와 쌍곡선 xy=4 는 x 와 y 를 바꿔도 식이 그대로라 자기 자신과 겹친다는 것도 함께 알려 준다. 이어 f(x,y)=0 → f(y,x)=0 규칙으로 방정식 6문제를 4지선다로 푼다(y=2x+1 → x=2y+1, (x−3)²+(y−1)²=4 → (x−1)²+(y−3)²=4, y=x²−2 → x=y²−2, 3x−2y+6=0 → 2x−3y−6=0, x²+y²−4x+2y=0 → x²+y²+2x−4y=0, y=|x|−2 → x=|y|−2). 선택지에는 부호를 바꾸는 다른 대칭과 헷갈리게 만든 함정이 들어 있다. ③삼각형 퍼즐 — 대칭축이 없어 여덟 가지 변환이 모두 구별되는 삼각형 (1,1)·(4,1)·(1,3) 을 여덟 개의 버튼(왼쪽·오른쪽·위·아래 한 칸씩과 x축·y축·원점·y=x 대칭)으로 옮겨 회색 목표 자리에 정확히 겹치는 퍼즐 여섯 판. 한 번 되돌리기와 처음부터 버튼이 있고, 세 꼭짓점의 좌표 변화와 누른 순서가 기록되며, 성공하면 최소 횟수와 비교해 별을 준다. 원점 대칭 버튼이 잠긴 판에서는 x축과 y축 대칭을 이어 해야 하고, 왼쪽 버튼이 잠긴 판에서는 y축 대칭으로 뒤집었다가 오른쪽으로 간 뒤 다시 뒤집는 방법을 찾아내야 하며, y = x 대칭 다음 x축 대칭을 하면 도형이 90° 돌아간다는 것도 한 판으로 다룬다. 마지막에는 평행이동 (x+a, y+b) / f(x−a, y−b)=0, x축 대칭 (x,−y) / f(x,−y)=0, y축 대칭 (−x,y) / f(−x,y)=0, 원점 대칭 (−x,−y) / f(−x,−y)=0, y=x 대칭 (y,x) / f(y,x)=0 을 점과 도형 두 열로 나란히 놓은 요약표로 중단원을 정리하며, 평행이동만 부호가 반대로 들어가고 대칭이동 넷은 점과 도형의 계산이 같다는 점을 짚는다. 여덟 장의 카드가 서로 정확히 y=x 대칭인지와 대각선 위의 점이 섞여 있지 않은지, 여섯 도형의 곡선 표본점이 모두 식을 만족하고 자기대칭 판정이 실제 변환 결과 및 정리한 식과 앞뒤가 맞는지, 퀴즈 여섯 문제의 정답이 무작위 4,000점 대입으로 성립하는지, 퍼즐 여섯 판의 최소 횟수가 너비 우선 탐색 결과와 같고 잠긴 버튼이 실제로 횟수를 늘리는지, 기준 삼각형이 여덟 변환에서 모두 다른 자리로 가는지를 전수 검산했다. 대칭이동의 수직·중점·등거리 성질은 무작위 3,000회, 여덟 변환 규칙과 합성 성질은 무작위 2,000점으로 확인했고, 활동에서 만들어지는 수식은 전부 렌더 테스트를 거쳤다.$ov$, now()),
  ($s$common2/mini/general_symmetry_lab$s$, $ov$점대칭과 선대칭의 일반화를 세 탭으로 다루는 활동. 교과서의 복잡한 일반식을 외우게 하는 대신 ''중점''과 ''수선의 발'' 두 도구만으로 어떤 대칭이든 만들어 내도록 구성했다. ①점 (a, b) 대칭 — 기준점 O 와 점 P 를 각각 끌면 P′ 이 따라 움직이고, O 가 PP′ 의 중점임을 뜻하는 빗금이 양쪽에 그려진다. 오른쪽에는 현재 좌표를 넣은 중점 조건 (x+x′)/2 = a, (y+y′)/2 = b 에서 x′ = 2a − x, y′ = 2b − y 가 나오는 과정이 실시간으로 갱신되어, 공식을 외우지 않아도 그때그때 만들어 낼 수 있음을 보여 준다. ''도형도 함께 옮겨 보기''를 켜면 원 (x−1)²+(y+1)²=4 가 함께 점대칭되며 중심만 옮기면 된다는 것을 확인할 수 있다. 이어 점의 대칭점을 구하는 3문제를 좌표 두 칸으로 풀고(P(3,1) 을 (2,−1) 에 대해 → (1,−3) 등), 도형 문제 2개를 4지선다로 푼다(원 (x−1)²+(y−2)²=9 를 (3,0) 에 대해 → (x−5)²+(y+2)²=9, 직선 y=2x+1 을 (1,1) 에 대해 → y=2x−3). ②직선 l 대칭 — a·b·c 세 슬라이더로 직선 ax+by+c=0 을 자유롭게 바꾸고 점 P 를 끌면, 수선의 발 H 와 대칭점 P′ 이 직각 표시·등호 빗금과 함께 그려진다. 교과서의 두 조건(PP′ 의 중점이 l 위에 있다, PP′ 이 l 과 수직이다)이 실제 수치로 0 이 되는 것을 보여 주고, 대칭점은 ''수선의 발 H 를 찾고 P′ = 2H − P'' 라는 두 걸음으로 구한다. 교과서의 일반식은 접이식 카드에 넣어 두되 외울 필요가 없다는 안내를 붙였다(활동의 계산 결과가 그 일반식과 완전히 일치함은 검산으로 확인했다). 문제는 H 를 구하고 → P′ = 2H − P 로 잇는 2단계 빈칸으로 6개이며, 가로선 y+1=0, 세로선 x−2=0, 기울기 ±1 인 직선, 그리고 2x+y−5=0 · x−2y=0 같은 일반 직선까지 다뤄 H 와 P′ 이 모두 정수로 떨어지도록 골랐다. ③탐정 게임 — 대칭축이 없는 삼각형과 그 상이 주어지고, 학생은 ''대응점 이어 보기'' 단서를 켜서 선분들이 한 점에서 만나는지(점대칭) 서로 나란한지(선대칭)를 판단한 뒤, 점대칭이면 중심 O 를 끌어다 놓고 선대칭이면 두 점 A·B 를 끌어 거울 직선을 맞춘다. 여섯 사건은 점대칭 3개(중심 (2,1), (0,−2), (−1,2))와 선대칭 3개(거울 x=1, y=x−1, y=−x+3)로 이루어져 있다. 판정은 모든 대응쌍의 중점이 한 점인지(중심) 또는 중점이 직선 위에 있고 PP′ 과 수직인지(거울)로 이루어져, 정답 자리에서만 통과한다. 마지막에는 점대칭은 중점 하나, 선대칭은 수선의 발 하나면 된다는 두 줄 요약으로 마무리한다. 점대칭과 선대칭의 중점·수직·거리 성질과 두 번 하면 제자리가 되는 성질을 각각 무작위 4,000회로 확인했고, 특히 이 활동의 선대칭 계산이 교과서의 복잡한 일반식과 완전히 같은 값을 주는지도 무작위 4,000회로 검산했다. 문제의 수선의 발과 대칭점이 모두 정수인지, 도형 문제의 정답이 무작위 4,000점 대입으로 성립하는지, 탐정 게임 여섯 사건의 상이 정수이고 화면 안에 들어오는지, 점대칭은 도형의 방향을 보존하고 선대칭은 뒤집어 두 유형이 절대 헷갈리지 않는지, 격자 위 모든 후보점과 모든 후보 직선을 전수 탐색해 정답만 기준으로 인정되는지를 검산했다. 활동에서 만들어지는 수식은 전부 렌더 테스트를 거쳤다.$ov$, now()),
  ($s$common2/mini/shortest_path_lab$s$, $ov$대칭이동을 이용해 최단 거리를 찾는 활동을 세 탭으로 구성했다. 꺾인 길을 거울로 펴서 직선으로 바꾸는 아이디어를 조작으로 익힌 뒤 실생활 문제와 두 번 반사 문제까지 나아간다. ①왜 대칭점일까 — 거울(x축) 위의 점 P 를 끌면 A 에서 P 를 거쳐 B 로 가는 길의 길이가 실시간으로 표시되고, 가장 짧은 길이와 비교해 얼마나 더 긴지 알려 준다. 정확한 자리에 놓으면 별이 켜지며, 두 지점 A, B 도 끌어 옮길 수 있어 여러 배치에서 반복해 볼 수 있다. ''거울에 비친 B′ 보기''를 켜면 대칭점 B′ 과 PB = PB′ 을 뜻하는 빗금, 그리고 A 에서 B′ 까지의 직선이 함께 나타나 꺾인 길이 곧게 펴지는 모습이 드러난다. 옆에는 P 의 위치에 따라 길이가 어떻게 변하는지 골짜기 모양 그래프로 그려 최솟값의 자리를 눈으로 확인하게 했다. 최단 경로를 한 번 찾으면 PB = PB′ → AP + PB = AP + PB′ → 삼각부등식 AB′ ≤ AP + PB′ → 최솟값은 AB′ 로 이어지는 네 줄 증명이 열린다. ②생활 속 최단 거리 — 자전거 도로 위 정비소 자리, 큰길가 마을버스 정류장 자리, 고속도로 옆 전기차 충전소 자리, 강에서 물을 채우는 소방 헬기의 급수 지점 네 가지 상황을 다룬다. 거울이 x축·y축·가로선 y=2 로 다양해 어떤 직선에도 같은 방법이 통함을 보여 준다. 문제는 대칭점 B′ 의 좌표 → 최솟값 AB′ → 가장 좋은 자리 P 의 좌표 3단계 빈칸으로 풀며, 단계를 맞힐 때마다 그림이 한 겹씩 열려 대칭점·펴진 직선·실제 경로가 차례로 나타난다. 네 문제 모두 최솟값과 최적 지점이 정수로 떨어지도록 골랐다(각각 10 km, 15 km, 10 km, 10 km). ③두 번 튕기기 — 두 벽이 거울인 방에서 아래 거울과 왼쪽 거울에 한 번씩 반사시켜 목표에 맞히는 퍼즐 세 판(레이저 보안 장치 14×10, 벽치기 연습 24×16, 전파 중계 40×20). 아래 거울 위의 점 A 를 끌면 반사 법칙에 따라 경로가 실시간으로 다시 그려지고, 목표를 얼마나 빗나갔는지 거리로 알려 준다. 맞히면 두 번째 반사점 B 의 좌표가 표시되고, ''양끝을 거울에 비춰 펴 보기''를 켜면 출발점을 아래 거울에 비춘 S′(Sx, −Sy) 과 목표점을 왼쪽 거울에 비춘 T′(−Tx, Ty) 이 나타난다. 이때 선분 S′T′ 이 두 거울과 만나는 곳이 곧 두 반사점 A, B 이므로 직선 하나를 긋는 것만으로 반사점을 찾을 수 있고, SA = S′A 이고 BT = BT′ 이라 길이도 그대로 보존된다. 마지막으로 전체 이동 거리를 입력해 S′T′ = √{(Sx+Tx)² + (Sy+Ty)²} 로 한 번에 구할 수 있음을 확인한다(각각 20 m, 30 m, 50 m). 최단 경로의 원리는 무작위 4,000회로 검산했다 — 대칭점의 중점 성질, PB = PB′, 최솟값이 AB′ 과 같음, 그리고 거울 위의 다른 어떤 점도 더 짧지 않음을 함께 확인했다. 네 실생활 문제는 최솟값과 최적 지점이 정수인지, 두 지점이 거울의 같은 쪽에 있는지, 거울 위를 0.25 간격으로 훑어 더 짧은 점이 없는지 검산했고, 세 반사 퍼즐은 정답 반사점이 정수이고 방 안에 있는지, 두 벽 모두에서 입사각과 반사각이 같은지, 경로 세 조각의 합이 펴 놓은 직선의 길이와 같은지, 그리고 목표를 맞히는 반사점이 오직 하나뿐인지를 전수 탐색으로 확인했다. 또 선분 S′T′ 이 두 거울과 만나는 점이 정확히 A, B 이고 아래 거울을 먼저 지나며 SA = S′A · BT = BT′ 이 성립하는지를 무작위 3,000회의 배치로 검산했다. 교과서에서 다룬 문제와 겹치지 않도록 상황과 수치를 새로 만들었다. 활동에서 만들어지는 수식은 전부 렌더 테스트를 거쳤다.$ov$, now()),
  ($s$common2/mini/tessellation_lab$s$, $ov$이 중단원에서 배운 도형의 이동만으로 테셀레이션(쪽매 맞춤)을 만들어 보는 두 탭 활동. 조각을 정교하게 디자인하는 것이 목적이 아니라, 평행이동과 대칭이동이 평면을 빈틈없이 채우는 데 그대로 쓰인다는 것을 손으로 확인하는 데 목적을 두었다. ①쪽매 조각 만들기 — 가로 4, 세로 3 인 직사각형 한 칸에서 출발해 변 위의 노란 조절점을 끌면 조각의 모양이 바뀐다. 회색 빈 점은 고른 방식에 따라 저절로 따라 움직여, 한쪽에서 잘라낸 부분이 반대쪽에 그대로 붙는 모습을 보여 준다. 붙이는 방식은 네 가지다. 평행이동 방식은 왼쪽에서 잘라 오른쪽에·아래에서 잘라 위에 그대로 옮겨 붙이고, 점대칭 방식은 각 변을 그 변의 한가운데를 중심으로 180° 돌린 모양으로 만들며, 선대칭 방식은 위·아래 변을 좌우 대칭으로 만들고 옆 변을 곧게 두고, 미끄럼반사 방식은 위 변을 아래 변의 거울상으로 만든다. 어떤 방식으로 어떻게 변형해도 조각의 넓이가 언제나 4 × 3 = 12 로 그대로임을 수치로 확인하게 했고, 물고기·화살·톱니·나뭇잎 네 가지 모양을 미리 담아 두어 바로 불러올 수 있다. ②옮기고 뒤집어 붙이기 — 앞 탭에서 만든 조각이 그대로 넘어와 4 × 3 = 12 칸의 격자를 채운다. 자동으로 채워 주지 않고, 학생이 손에 든 조각에 직접 이동을 주어 맞춰야 한다. 왼쪽·오른쪽·위·아래 버튼으로 한 칸씩 평행이동하고, 180° 회전·좌우 뒤집기·위아래 뒤집기 버튼으로 자세를 바꾼 뒤 붙인다. 손에 든 조각은 지금 자리에 맞물리면 초록 실선, 맞물리지 않으면 붉은 점선으로 미리 보여 주므로, 버튼을 눌러 가며 어떤 이동이 필요한지 스스로 찾게 된다. 맞물림 판정은 자세 이름을 비교하는 것이 아니라 놓인 도형이 그 칸의 조각과 실제로 같은지를 꼭짓점 단위로 확인하므로, 조각이 대칭이어서 여러 자세가 모두 통하는 경우도 정직하게 인정된다. 붙인 조각은 쓴 이동의 종류별로 색이 달라 무늬 안에서 평행이동 칸과 뒤집힌 칸이 한눈에 구분되고, 다 채우면 겹친 곳도 틈도 없다는 것을 조각 수 × 넓이로 확인한다. 힌트는 그 칸에 필요한 자세를 알려 주며, 미끄럼반사 방식에서는 좌우로 뒤집고 위로 옮긴 것이 곧 미끄럼반사임을 짚어 준다. 칸을 눌러 조각을 그 자리로 바로 옮길 수도 있고, 지우기·한 번에 채우기·칸 선을 지우고 무늬만 보기 버튼을 두었으며, 네 가지 방식이 각각 어떤 이동을 쓰는지 비교하는 표로 마무리한다. 같은 조각이라도 붙이는 이동에 따라 무늬가 달라진다는 점을 강조한다. 네 방식과 0.5 간격의 모든 조절점 조합 1,575가지에 대해 조각의 넓이가 정확히 12 인지, 다각형이 스스로 꼬이지 않는지, 그리고 조각을 격자에 배치했을 때 빈틈이나 겹침이 없는지를(격자 경계를 피한 표본점이 언제나 정확히 한 조각에만 들어가는지) 전수 검산했다. 조절점의 허용 범위는 이 전수 검사로 실제 안전한 구간만 남겨 정한 것이다. 또 격자에 놓이는 모든 조각에 대해 변의 길이와 넓이가 보존되는지, 실제 좌표 변환이 표시된 이동과 일치하는지, 평행이동과 회전은 도형의 방향을 보존하고 선대칭과 미끄럼반사는 방향을 뒤집는지까지 확인했다. 탭②의 조작 규칙도 같은 방식으로 검산했다. 네 가지 자세(그대로·180° 회전·좌우 뒤집기·위아래 뒤집기)가 모두 길이와 넓이를 보존하고 자기 칸 근처에 머무는지, 같은 조작을 두 번 하면 제자리로 돌아오고 좌우 뒤집기 다음 위아래 뒤집기가 180° 회전과 같은지, 어떤 자세에서든 네 자세 모두에 도달할 수 있는지, 그리고 각 칸에서 정답으로 안내하는 자세가 실제 타일링 조각과 정확히 일치하는지를 모든 조절점 조합에 대해 확인했다.$ov$, now()),
  ($s$common2/mini/move_card_lab$s$, $ov$네 장의 행동 카드로 좌표평면 위의 점을 옮기는 카드 놀이를 세 탭으로 구성했다. 카드는 x축의 방향으로 1만큼 평행이동하기(n회 반복), y축의 방향으로 1만큼 평행이동하기(n회 반복), 원점에 대하여 대칭이동하기, 직선 y = x 에 대하여 대칭이동하기 네 가지이며, 평행이동 카드 한 장 이상과 대칭 카드 한 장 이상을 반드시 쓰고 왼쪽부터 차례대로 실행한다는 규칙을 따른다. 반복 횟수가 자연수이므로 평행이동만으로는 오른쪽·위쪽으로만 갈 수 있고, 왼쪽이나 아래쪽 목표에 닿으려면 대칭 카드로 방향을 뒤집어야 한다는 점이 이 놀이의 핵심이다. ①카드로 점 옮기기 — 카드 덱에서 카드를 눌러 오른쪽 끝에 놓고, 반복 횟수를 정하고, 순서를 앞뒤로 바꾸거나 빼면서 별 모양 목표까지 옮긴다. 경로는 카드 색깔의 화살표로 실시간으로 그려지고 ''한 걸음씩 실행''을 누르면 1만큼씩 옮겨 가는 모습을 차례로 보여 준다. 규칙을 지켰는지(평행이동 ✓ / 대칭 ✓)가 배지로 표시되고, 카드마다의 도착점이 좌표로 나열되며, 도착하면 쓴 카드 수를 가장 적은 카드 수와 견주어 별 세 개까지 준다. 미션은 여섯 가지다 — (1,1)→(4,1) 최소 2장, (2,3)→(−5,−3) 최소 2장, (−3,−1)→(1,4) 최소 3장, (0,0)→(3,−2) 최소 3장, (−4,2)→(2,−4) 최소 3장, 그리고 가까워 보이지만 왼쪽으로는 갈 수 없어 대칭을 두 번 써야 하는 (−1,5)→(−3,6) 최소 4장. ②순서를 바꾸면? — 같은 카드 두 장을 순서만 바꿔 실행했을 때 도착점이 같은지 먼저 예상하고 확인한다. 맞히면 두 경로가 파랑·분홍으로 한 좌표평면에 겹쳐 그려지고 카드마다의 좌표가 나란히 표시되며, 출발점을 끌어 다른 자리에서도 확인할 수 있다. 네 짝을 모두 맞히면 평행이동끼리·대칭끼리는 순서를 바꿔도 되지만 평행이동과 대칭을 섞으면 순서가 중요하다는 정리가 열린다. ③대칭 카드의 비밀 — 평행이동 카드를 빼고 대칭 카드 두 장만 번갈아 누르면 아무리 눌러도 네 자리를 벗어날 수 없다는 것을 스스로 발견한다. 처음 자리 (x,y), 원점 대칭 (−x,−y), y = x 대칭 (y,x), 그리고 두 대칭을 이어 한 (−y,−x) 네 자리가 하나씩 밝혀지며, 좌표평면에는 y = x 와 y = −x 두 대칭축이 안내선으로 그려진다. 네 자리를 모두 찾으면 원점 대칭 다음 y = x 대칭이 어떤 대칭 한 번과 같은지를 묻는 문제가 열리고, 답이 직선 y = −x 에 대한 대칭임을 확인한다. 네 카드의 좌표 규칙과 대칭을 두 번 하면 제자리가 되는 성질, 두 대칭의 합성이 y = −x 대칭이 되고 순서를 바꿔도 같다는 것을 무작위 4,000회로 검산했고, 낱낱의 걸음으로 계산한 도착점과 카드 단위로 계산한 도착점이 같은지를 무작위 3,000개 카드 배열로 확인했다. 여섯 미션의 최소 카드 수는 좌표 범위를 제한한 너비 우선 탐색으로 다시 구해 대조했으며(처음 적어 둔 값 하나가 실제와 달라 미션 구성을 다시 잡았다), 순서를 바꿔도 되는 짝과 안 되는 짝의 판정도 무작위 2,000회로 검산했다. 대칭 카드만으로 도달할 수 있는 자리가 정확히 네 곳뿐이라는 것도 탐색으로 확인했다.$ov$, now()),
  ($s$common2/mini/set_notation_lab$s$, $ov$네 탭으로 집합의 뜻과 표현을 익히는 활동이다. ①집합일까? — 여덟 장의 「모임 카드」를 한 장씩 넘기며 집합인지 아닌지를 갈라 담는다. 15의 약수의 모임, 방정식 x^2-5x+6=0 의 해의 모임, 20보다 작은 소수의 모임, MATH 에 쓰인 알파벳의 모임, 한 자리 자연수 중 3의 배수의 모임은 조건이 분명하여 집합이고, 키가 큰 학생의 모임·맛이 좋은 과일의 모임·0에 가까운 정수의 모임은 기준이 사람마다 달라 집합이 아니다. 집합이라고 옳게 판정하면 곧바로 원소 고르기 단계가 열려, 후보 칩 가운데 원소인 것만 골라 담아야 한다(원소는 초록, 원소가 아닌 것은 빨강으로 즉시 표시). MATH 카드는 같은 글자가 여러 번 나와도 원소로는 한 번만 쓴다는 점을, 여덟 장을 모두 마치면 「집합이 아닌 모임에는 사람마다 기준이 다른 말이 들어 있었다」는 정리를 보여 준다. ②기호 바구니 — 조건제시법으로 주어진 집합에 대하여 화면 위쪽에 놓인 수 공들을 끌어다 ∈ 바구니와 ∉ 바구니에 나누어 담는다. 드래그하는 동안 손이 올라간 바구니가 밝아지고, 잘못 담으면 공이 제자리로 튕겨 돌아오며 되돌아온 횟수가 쌓인다. 네 라운드는 A: 18의 약수, B: 20보다 작은 소수, C: 24의 약수 중 짝수, D: 30 이하의 4의 배수이며, 모두 담으면 그 집합의 원소나열법과 a∈A·b∉B 꼴의 기호 문장 두 개가 나타난다. 집합은 알파벳 대문자로, 원소는 알파벳 소문자로 쓴다는 약속도 함께 안내한다. ③표현 바꾸기 — 여섯 문제를 두 방향으로 오간다. 원소나열법 → 조건제시법 세 문제는 「x는 [범위] [대상]」의 두 칸을 범위 여섯 가지(10 이하의·10보다 작은·20 이하의·20보다 작은·30 이하의·40 이하의)와 대상 여덟 가지(자연수·짝수·홀수·소수·3의 배수·4의 배수·5의 배수·6의 배수) 중에서 골라 조립하는데, 고른 조건이 실제로 만들어 내는 집합을 그때그때 계산해 목표 집합과 견주므로 더 들어간 원소는 빨강, 빠진 원소는 노란 점선으로 바로 드러난다. 판정이 이름 대조가 아니라 집합의 일치로 이루어지므로 {2, 3, 5, 7} 처럼 「10 이하의 소수」와 「10보다 작은 소수」가 모두 정답으로 인정되고, 맞힌 뒤에는 같은 집합을 나타내는 다른 조건도 함께 보여 주어 조건제시법의 표현이 하나가 아님을 확인한다. 조건제시법 → 원소나열법 세 문제(24의 약수, 15보다 작은 소수, 방정식 x^2-7x+12=0 의 해)는 후보 칩에서 원소만 골라 담는다. 여섯 문제를 모두 마치면 두 표현법의 장단점(원소를 구체적으로 확인하기 편리 ↔ 원소가 많은 집합을 나타내기 편리)이 정리된다. ④집합 탐정 — 숨은 조건을 가진 집합에 1부터 24까지의 수를 하나씩 눌러 ∈인지 ∉인지 물어보며 정체를 알아낸 뒤, 조건제시법 네 선택지 중에서 고른다. 숨은 집합은 4의 배수, 소수, 24의 약수, 어떤 자연수의 제곱 네 가지이며 질문 횟수가 적을수록 별을 많이 받는다. 맞히면 집합 전체를 원소나열법으로 공개하고 어떤 단서로 가려낼 수 있었는지 짚어 준다. 데이터는 node로 모두 검산했다 — 카드의 원소와 방정식의 해, 네 라운드 집합의 원소, 각 라운드의 ∈·∉ 공이 한쪽으로 치우치지 않는지를 확인했고, 범위 6가지 × 대상 8가지 48개 조합을 전수 계산해 조건 조립 문제마다 정답 조합이 실제로 존재하는지와 몇 가지인지를 확인했으며(v1은 2가지, v3·v5는 1가지), 탐정 문제는 네 선택지가 1부터 24까지 안에서 서로 모두 다른 집합이 되는지와 정답 외에 다른 선택지가 답이 되지 않는지를 전수 대조했다. 활동에서 만들어지는 KaTeX 수식 102개도 모두 렌더해 오류가 없고 수식 안에 한글이 섞이지 않았음을 확인했다.$ov$, now()),
  ($s$common2/mini/set_game_lab$s$, $ov$보드게임 SET 을 네 탭으로 옮겨 온 놀이 활동이다. 세 장의 카드가 「합」(SET)이 되려면 모든 속성이 각각 모두 같거나 모두 달라야 한다. 카드는 모두 인라인 SVG 로 그렸다 — 긴 원은 양 끝이 둥근 알약 모양, 마름모는 네 꼭짓점 다각형, 물결은 가운데 선 x = 50 + 16 sin(2πt) 를 굵기 34 의 띠로 부풀리고 양 끝을 반원으로 막아 만든 윤곽선(점 116개)이며, 카드 바탕과 주황 테두리도 수업 자료의 카드 모습을 따랐다. ①합의 규칙 — 모양·색깔·개수 세 속성의 조건을 보여 주고, 「카드 27장 모두 보기」를 열면 모양 3 × 색깔 3 열과 개수 3 행으로 짜인 27장 표가 펼쳐져 3 × 3 × 3 = 27 을 눈으로 확인한다. 이어 세 장이 합인지 아닌지를 가리는 문제 여섯 개를 푼다(합 셋 · 아님 셋). 맞히면 모양·색깔·개수 각각이 「모두 같아요 / 모두 달라요 / 두 장만 같아요」 중 어느 상태인지 줄마다 보여 준다. 합이 아닌 세 문제는 각각 색깔·모양·개수에서 어긋나도록 골랐고, 특히 마지막 문제는 모양과 색깔은 모두 다른데 개수만 1·2·1 이라 눈에 잘 띄지 않는 속성까지 확인하게 한다. ②세 번째 카드 — 두 장이 주어졌을 때 합이 되는 나머지 한 장을 모양·색깔·개수를 하나씩 골라 직접 만든다. 고르는 대로 미리보기 카드가 그려지고, 셋을 모두 고르면 속성별 판정이 나타난다. 다섯 문제를 마치면 「속성마다 둘이 같으면 그대로, 둘이 다르면 남은 하나」이므로 세 번째 카드가 언제나 딱 하나로 정해진다는 정리가 열린다. ③합 모두 찾기 — 9장이 3 × 3 으로 놓인 상황 넷에서 합을 남김없이 찾는다. 카드 세 장을 고르면 곧바로 판정해 합이면 초록으로 기록되고 아니면 잠깐 빨갛게 표시된 뒤 선택이 풀린다. 카드 한 장을 알려 주는 힌트와 못 찾은 합을 보여 주는 단추가 있고, 다 찾으면 9장에서 세 장을 고르는 84가지 가운데 합이 몇 가지뿐이었는지를 짚어 준다. 네 상황의 합은 각각 3·4·4·5개다. ④SET 보드게임 — 네 번째 속성인 무늬(채움·줄무늬·테두리)가 더해진 81장으로 실제 보드게임을 한다. 12장을 펼쳐 놓고 합을 찾아 가져가면 빈자리가 새 카드로 채워지며, 합이 전혀 없을 때만 3장을 더 펼칠 수 있다(합이 남아 있는데 누르면 실수로 센다). 모은 합·남은 카드·실수·시간이 실시간으로 표시되고, 카드를 다 쓰고 더 이상 합이 없으면 게임이 끝난다. 데이터는 node 로 전수 검산했다 — 「모두 같거나 모두 다르다」가 속성값 세 개의 합이 3의 배수인 것과 같음을 27가지 경우로 확인했고, 27장 전체의 합이 117개(= 27·26/6), 81장 전체의 합이 1,080개(= 81·80/6)임을 전수 계산으로 맞추었으며, 두 장을 고르는 3,240가지 짝 모두에 대하여 합이 되는 세 번째 카드가 정확히 한 장뿐임을 확인했다. 탭①의 여섯 문제는 판정과 속성별 상태가 일치하는지, 합이 아닌 문제들이 서로 다른 속성에서 어긋나는지를 확인했고, 탭③의 네 상황은 합의 개수를 전수 조사해 3·4·4·5 인 것과 한 색깔·한 모양·한 개수로 치우치지 않는 것을 확인했다. 보드게임은 무작위 2,000판을 돌려 12장에 합이 없어 3장을 더 펼치게 되는 판이 약 2.7%이고 펼친 카드가 21장을 넘는 일이 없으며 한 판에 평균 24.4개의 합을 모으게 됨을 확인했다. 물결 윤곽선은 100 × 200 상자를 벗어나지 않고 긴 원·마름모와 가로 폭이 같으며 점대칭이고 스스로 만나지 않음을 좌표 전수 대조로 확인했다.$ov$, now()),
  ($s$common2/mini/subset_lab$s$, $ov$부분집합·상등·진부분집합·벤 다이어그램을 네 탭으로 익히는 활동이다. ①원소 검문소 — A 의 원소 하나하나를 눌러 B 안에 있는지 검사한다. 누른 원소는 B 에 있으면 초록, 없으면 빨강으로 바뀌고 아래 B 상자에서 짝이 되는 원소가 함께 밝아지며 「통과!」인지 「여기서 걸렸어요!」인지 말해 준다. 검사를 마치면 A ⊂ B 인지 A ⊄ B 인지 판정한다. 여섯 문제는 {1,3}과 {1,2,3,4}, {2,5,9}와 {2,4,6,8}, 9의 약수와 18의 약수, 방정식 x^2-5x+4=0 의 해와 {2,4,6}, 공집합과 {a,b,c}, 그리고 {5,10,15}와 15 이하의 5의 배수로, 마지막 두 문제로 공집합이 모든 집합의 부분집합이라는 것과 자기 자신도 부분집합이라는 것을 짚는다. ②상등과 진부분집합 — 앞부분에서는 A ⊂ B 와 B ⊂ A 를 차례로 판정하고(앞 단계를 맞혀야 다음이 열린다) 마지막에 A = B 인지 A ≠ B 인지 고른다. 맞히면 두 집합의 원소가 상대에게 있는지 없는지에 따라 초록·빨강으로 칠해져 어느 원소 때문에 상등이 깨지는지가 한눈에 보인다. 뒷부분은 부분집합 모으기다. S = {1, 2, 4} 의 원소마다 넣을지 뺄지를 눌러 부분집합을 만들고 「담기」로 모으는데, 여덟 칸을 다 채워야 끝난다. 자기 자신을 만들면 「자기 자신이라 진부분집합은 아니에요」라고 알려 주고, 다 모으면 2^3 = 8 개와 진부분집합 2^3 - 1 = 7 개, 그리고 원소 개수에 따른 부분집합 개수 표가 열린다. ③벤 다이어그램 — 아래 대기 줄에 놓인 원소를 끌어다 원 안이나 밖에 놓아 그림을 완성한다. 드래그하는 동안 손이 올라간 영역의 원이 밝아지고, 자리를 잘못 놓으면 원소가 제자리로 돌아오며 되돌아온 횟수가 쌓인다. 판정은 이름 대조가 아니라 원의 중심에서 잰 거리로 하므로, 두 원이 겹친 자리에 놓으면 실제로 「두 집합 모두」로 인정된다. 네 그림은 원 하나(8의 약수 — 3과 6은 원 밖에 두어야 한다), 안쪽·바깥쪽 원(9의 약수와 18의 약수), 겹친 두 원(6의 약수와 10보다 작은 짝수), 떨어진 두 원({1,4,9}와 {2,3,5})이다. ④포함관계 그림 — A ⊂ B 인지, B ⊂ A 인지를 차례로 정하고, 그다음 다섯 가지 작은 그림 가운데 알맞은 것을 고른다. 맞히면 원소가 제자리에 놓인 벤 다이어그램이 그려진다. 다섯 문제로 B 안에 A · A 안에 B · 겹침 · A = B · 떨어짐 다섯 가지가 모두 나오는데, 특히 셋째와 다섯째 문제는 기호가 똑같이 A ⊄ B, B ⊄ A 인데도 함께 가진 원소가 있느냐 없느냐에 따라 그림이 겹침과 떨어짐으로 갈린다는 것을 견주어 보게 한다. 데이터는 node 로 전수 검산했다 — 9·18·8·12의 약수, 방정식 x^2-5x+4=0 과 x^2=9 의 해, 10보다 작은 홀수인 소수, 15 이하의 5의 배수, 10보다 작은 짝수, 7보다 작은 짝수인 자연수를 모두 다시 계산해 대조했고, 상등 판정이 (A⊂B 이고 B⊂A) 와 일치하는지, 세 원소 집합의 부분집합이 2^3 = 8 개이고 서로 모두 다르며 진부분집합이 7개인지, 열쇠와 원소 사이의 왕복이 어긋나지 않는지를 확인했다. 벤 다이어그램은 여섯 배치의 원이 모두 화면 안에 들어가는지, 안쪽 원이 바깥 원에 완전히 들어가는지, 겹침 배치가 실제로 겹치되 한쪽이 다른 쪽을 삼키지 않는지, 떨어짐 배치가 실제로 떨어지는지를 확인했고, 모든 문제의 모든 원소에 대하여 놓일 자리가 실제로 그 영역으로 판정되는지·화면을 벗어나지 않는지·칩끼리 겹치지 않는지를 좌표로 전수 검사했다. 활동에서 만들어지는 KaTeX 수식 56개도 모두 렌더해 오류가 없고 수식 안에 한글이 섞이지 않았음을 확인했다.$ov$, now()),
  ($s$common2/mini/subset_count_lab$s$, $ov$부분집합의 개수를 세는 방법을 네 탭으로 익히는 활동이다. 핵심은 원소 하나하나가 「넣는다 ○ / 넣지 않는다 ×」 두 갈래로 갈라진다는 것이다. ①갈림길 나무 — 원소 a, b, c 에 대한 수형도를 왼쪽부터 눌러 걸어간다. 앞 단계를 고른 뒤에야 다음 단계가 눌리고, 지나온 길이 밝게 이어지며 오른쪽 끝에 닿으면 부분집합 하나가 드러난다. 여덟 갈래를 모두 걸으면 2 × 2 × 2 = 2^3 = 8 과 「원소가 n개면 부분집합은 2^n 개」가 열린다. 수형도는 인라인 SVG 로 그렸고 넣기 ○ 를 위쪽으로 두어 잎이 {a,b,c}부터 공집합까지 차례로 놓인다. ②스위치 계산기 — 원소의 개수를 3부터 8까지 슬라이더로 바꾸고, 원소마다 스위치를 눌러 「자유 / 반드시 넣기 / 반드시 빼기」를 정한다. 못 박은 원소는 고를 것이 없으므로 곱해지는 수가 2 대신 1 로 바뀌고, 1 × 2 × 2 × 1 × … 의 곱과 2^(n-k-l) 이 그때그때 다시 계산되어 보인다. 다섯 미션은 n=4 모든 부분집합, n=5 에서 특정 2개 포함, n=6 에서 특정 1개 제외, n=7 에서 2개 포함·1개 제외, n=8 에서 3개 포함·2개 제외이며, 판정은 어느 원소를 골랐는지가 아니라 원소의 개수와 넣기·빼기의 개수로 이루어진다. ③개수 맞히기 — 여섯 문제의 답을 숫자로 적어 넣는다. 1부터 5까지의 부분집합(32), 1부터 6까지의 진부분집합(63), 1과 6을 모두 갖는 부분집합(16), a를 갖지 않는 부분집합(64), 2와 3은 갖고 7은 갖지 않는 부분집합(32), 원소의 최솟값이 3인 부분집합(16)이다. 「스위치로 보기」를 누르면 각 원소가 자유인지 못 박혔는지가 띠로 그려져 스스로 센 값을 견주어 볼 수 있다. ④부분집합 사냥 — 조건에 맞는 부분집합을 하나하나 직접 만들어 잡는다. 조건을 어기면 무엇이 빠졌는지 무엇이 더 들어갔는지 알려 주며 잡을 수 없고, 이미 잡은 것은 다시 잡히지 않는다. 세 라운드는 {1,2,3,4}에서 1과 3을 모두 갖는 것(4개), 2는 갖고 4는 갖지 않는 것(4개), {1,2,3,4,5}에서 원소의 최솟값이 2인 것(8개)이며, 다 잡으면 직접 센 개수와 2^(n-k-l) 이 맞아떨어지는 것을 확인한다. 데이터는 node 로 전수 검산했다 — 수형도의 여덟 갈래가 모든 부분집합을 꼭 한 번씩 만들어 내는지, 부모 마디의 높이가 자식 두 개의 한가운데인지, 같은 단계의 마디가 겹치지 않는지를 확인했고, 다섯 미션의 개수를 2^n 가지 경우 전수 조사로 대조했다. 탭③·탭④ 의 문제는 조건의 뜻을 따로 적어 전수 조사한 값과 적어 둔 답을 견주었고, 「원소의 최솟값이 3이다」 같은 말로 된 조건을 넣기·빼기로 옮긴 것이 실제로 똑같은 부분집합들을 고르는지도 2^n 가지 경우 모두에서 확인했다. 활동에서 만들어지는 KaTeX 수식 104개도 모두 렌더해 오류가 없고 수식 안에 한글이 섞이지 않았음을 확인했다.$ov$, now()),
  ($s$common2/mini/union_intersection_lab$s$, $ov$합집합과 교집합을 네 탭으로 익히는 활동이다. 벤 다이어그램은 모두 인라인 SVG 로 그렸고, 두 원이 만드는 세 영역은 잘라내기(clip-path)로 나누어 각각을 눌러 칠할 수 있게 했다. ①영역 색칠 — 두 집합이 주어지고 A ∪ B 또는 A ∩ B 를 나타내는 영역을 눌러 칠한다. 칠한 영역이 나타내는 집합이 그때그때 원소나열법으로 나타나므로, 합집합을 칠할 때 겹치는 자리를 빠뜨리면 원소가 모자란 것이 바로 보인다. 여섯 문제는 지훈이와 서연이가 듣는 방과후 수업의 교집합과 합집합, 6의 약수와 10보다 작은 짝수의 교집합, 12의 약수와 18의 약수의 교집합(두 수의 공약수), 20 이하의 4의 배수와 6의 배수의 합집합, 방정식 x^2-x-6=0 의 해와 {-2, 0, 2} 의 합집합이다. ②서로소 짝짓기 — 조건제시법으로 주어진 여섯 집합 카드 가운데 두 장을 골라 교집합을 확인한다. 공통인 원소가 있으면 그 원소가 두 카드 모두에서 빨갛게 드러나고, 공집합이면 서로소로 인정되어 짝 목록이 채워진다. 열다섯 쌍 가운데 서로소는 다섯 쌍이며, 모두 찾으면 A ∩ ∅ = ∅ 이므로 공집합은 모든 집합과 서로소라는 정리가 열린다. ③개수 계산기 — 먼저 n(A), n(B), n(A ∩ B) 를 슬라이더로 움직이는 시뮬레이터로 세 영역의 개수가 어떻게 나뉘는지 보며 n(A ∪ B) = n(A) + n(B) - n(A ∩ B) 를 발견한다. 이어 다섯 문제를 푼다 — 합집합 구하기, 합집합에서 거꾸로 교집합 구하기, 서로소일 때의 합집합, 세 집합의 포함·배제, 그리고 등산과 자전거를 좋아하는 학생 수를 묻는 실생활 문제다. 맞히면 벤 다이어그램에 영역별 개수가 채워지고(세 집합 문제는 일곱 영역이 모두 채워진 세 원 그림) 계산 과정이 함께 나타난다. ④최대와 최소 — 전체 집합 U 를 사각형으로 그린 벤 다이어그램에서 겹침 n(A ∩ B) 를 슬라이더로 움직인다. 겹침을 줄이면 A ∪ B 가 커지는데 U 를 넘어서면 "U 밖으로 넘쳐요"라고 알려 주고, 살펴본 값이 가능·불가능으로 칸에 기록되어 가능한 범위가 눈으로 드러난다. 충분히 살펴본 뒤 최댓값과 최솟값을 적어 넣는다. 세 문제는 학생 30명 중 강아지 19명·고양이 16명(최대 16, 최소 5), 회원 24명 중 축구 15명·농구 13명(최대 13, 최소 4), 학생 32명 중 영화 20명·뮤지컬 9명(최대 9, 최소 0)이며, 마지막 문제로 n(A) + n(B) 가 n(U) 이하이면 두 집합을 서로소로 놓을 수 있어 최솟값이 0 이 된다는 것을 앞의 두 문제와 견주게 한다. 데이터는 node 로 전수 검산했다 — 여섯 문제의 합집합·교집합을 정의 그대로 다시 계산해 대조하고, 칠해야 할 영역의 원소가 결과와 같은지 확인했다. 6·12·18의 약수와 방정식 x^2-x-6=0 의 해, 카드 여섯 장의 조건제시법 원소도 모두 다시 계산했고, 서로소인 다섯 쌍을 열다섯 쌍 전수 조사로 대조했다. n(A ∪ B) 공식은 n(A), n(B), n(A ∩ B) 가 가질 수 있는 819가지 조합에서 실제 원소를 만들어 세어 확인했고, 세 집합의 포함·배제의 원리도 무작위 3,000회로 확인했다. 최대·최소는 겹침이 가질 수 있는 값을 전수 조사해 적어 둔 값과 맞추었다. 두 원의 겹침이 알맞은지, 원소를 놓을 자리가 모두 제 영역 안이며 화면을 벗어나지 않는지, 세 원 그림의 일곱 영역 자리가 모두 제 영역으로 판정되는지도 좌표로 전수 검사했다. 방과후 수업처럼 원소가 한글인 집합은 KaTeX 로 그릴 수 없으므로 HTML 로 나타내도록 갈라 두었고, 활동에서 만들어지는 수식 70개를 모두 렌더해 오류가 없고 수식 안에 한글이 섞이지 않았음을 확인했다.$ov$, now()),
  ($s$common2/mini/set_law_lab$s$, $ov$집합의 연산법칙을 네 탭으로 익히는 활동이다. 벤 다이어그램의 조각(두 원이면 3조각, 세 원이면 7조각)을 하나씩 눌러 칠할 수 있게 인라인 SVG 로 그렸는데, 각 조각은 원 안쪽·바깥쪽 잘라내기를 겹쳐 만들었으므로 눌리는 자리도 실제 조각 모양 그대로다. ①교환·결합법칙 — 좌변과 우변의 식을 각각 다른 벤 다이어그램에 칠해 보고, 둘 다 알맞게 칠하면 「두 영역이 완전히 같아요」라는 판정과 법칙 이름이 나타난다. 네 문제는 A ∪ B = B ∪ A, A ∩ B = B ∩ A(두 원), (A ∪ B) ∪ C = A ∪ (B ∪ C), (A ∩ B) ∩ C = A ∩ (B ∩ C)(세 원)이며, 결합법칙 문제를 맞히면 괄호를 지우고 A ∪ B ∪ C 처럼 써도 된다는 안내가 함께 나온다. ②분배법칙 — 같은 방식으로 A ∩ (B ∪ C) = (A ∩ B) ∪ (A ∩ C), A ∪ (B ∩ C) = (A ∪ B) ∩ (A ∪ C), (A ∪ B) ∩ C = (A ∩ C) ∪ (B ∩ C), (A ∩ B) ∪ C = (A ∪ C) ∩ (B ∪ C) 네 문제를 푼다. 맞히면 오른쪽 식을 두 조각으로 쪼갠 작은 벤 다이어그램이 나란히 그려져, 조각을 각각 구해 합치면 왼쪽과 같아진다는 것을 눈으로 확인한다. ③수와 견주기 — 앞부분은 짝짓기다. 수의 연산법칙 다섯 개와 집합의 연산법칙 다섯 개를 섞어 놓고 같은 법칙끼리 이어 준다(∪ 는 +, ∩ 은 × 와 닮았다는 안내가 붙는다). 뒷부분이 이 탭의 핵심으로, 집합의 A ∪ (B ∩ C) = (A ∪ B) ∩ (A ∪ C) 를 수로 옮긴 a + b × c = (a+b) × (a+c) 가 정말 성립하는지 a, b, c 슬라이더로 따져 본다. a = 0 에서 시작하므로 처음에는 두 값이 같지만 a 를 올리면 곧 달라지며, 반례를 찾는 순간 수에서는 깨지는 이 모양이 집합에서는 언제나 참임을 벤 다이어그램 두 개로 대비해 보여 준다. ④법칙 탐정 — 여섯 등식이 언제나 성립하는지 가린다. 흡수법칙 A ∪ (A ∩ B) = A 와 A ∩ (A ∪ B) = A, 분배법칙을 뒤집어 쓴 것은 참이고, 괄호를 엉뚱한 자리로 옮긴 세 개는 거짓이다. 맞히면 두 식의 영역을 겹쳐 그려 양쪽 모두에 있는 조각은 초록, 한쪽에만 있는 조각은 빨강으로 보여 주고, 어긋나는 조각이 「C에만 있는 부분」처럼 말로도 설명된다. 데이터는 node 로 전수 검산했다 — 식 28개가 나타내는 영역을 조각마다 원소를 하나씩 두고 실제 합집합·교집합을 계산해 대조했고, 탭①·②의 여덟 문제는 좌우 영역이 실제로 일치하는지, 분배법칙 문제는 쪼갠 두 조각을 다시 합친 것이 오른쪽과 같은지, 좌우의 바깥 연산이 서로 다른지를 확인했다. 수의 분배법칙 a(b+c) = ab + ac 는 1,000가지에서 확인했고, 뒤집힌 모양 a + bc 와 (a+b)(a+c) 는 0부터 6까지 343가지를 전수 조사해 293가지에서 값이 다름을(그리고 a = 0 일 때는 언제나 같음을) 확인했다. 탭④의 여섯 등식은 일곱 조각을 모두 견주어 참·거짓과 어긋나는 조각을 대조했다(참 3 · 거짓 3). 두 그림의 조각 자리가 모두 제 조각으로 판정되는지, 원이 화면 안에 들어가고 서로 겹치되 한쪽이 다른 쪽을 삼키지 않는지도 좌표로 전수 검사했으며, 활동에서 만들어지는 KaTeX 수식 82개를 모두 렌더해 오류가 없고 수식 안에 한글이 섞이지 않았음을 확인했다.$ov$, now()),
  ($s$common2/mini/complement_lab$s$, $ov$여집합과 차집합을 네 탭으로 익히는 활동이다. 전체집합 U 를 둥근 사각형으로 그리고 그 안에 두 원을 놓아, U 안이 네 조각(두 원 바깥·A에만·B에만·겹치는 곳)으로 나뉜 벤 다이어그램을 인라인 SVG 로 그렸다. 각 조각은 원 안쪽·바깥쪽 잘라내기를 겹쳐 만들었으므로 눌리는 자리도 실제 조각 모양 그대로이며, 여집합을 다루기 위해 두 원 바깥 조각도 누를 수 있다. ①조각 칠하기 — 식이 나타내는 조각을 눌러 칠한다. 여섯 문제는 A^C, A - B, B - A, (A ∪ B)^C, A^C ∩ B, A - (A ∩ B) 이며, 다섯째와 여섯째를 맞히면 앞에서 칠한 B - A · A - B 와 똑같은 조각이라는 것을 짚어 준다. 여섯 문제를 마치면 A^C = U - A, A - A = ∅, A - ∅ = A, A - B ≠ B - A 를 정리해 보여 준다. 탭 아래에는 전체집합 바꾸기가 붙어 있어, A = {2, 4} 를 그대로 둔 채 전체집합만 5 이하의 자연수 · 10 이하의 짝수 · 8의 약수로 바꾸면 여집합이 {1,3,5} · {6,8,10} · {1,8} 로 달라지는 것을 눈으로 확인한다. ②성질 탐구 — 좌변과 우변을 각각 칠해 같은 조각인지 확인한다. 여섯 성질은 A - B = A ∩ B^C, (A^C)^C = A, A ∪ A^C = U, A ∩ A^C = ∅, A - B = A - (A ∩ B), 그리고 대칭차집합 (A - B) ∪ (B - A) = (A ∪ B) - (A ∩ B) 이다. A ∩ A^C 처럼 칠할 조각이 하나도 없는 식도 들어 있어 「빈 것」을 직접 만들어 보게 한다. ③원소로 구하기 — 원소를 하나 고른 뒤 벤 다이어그램의 조각을 눌러 넣는다. 자리를 잘못 고르면 들어가지 않고 헛짚음이 쌓인다. 두 세트는 U 가 8 이하의 자연수일 때 A = 8 이하의 짝수 · B = 6의 약수, U 가 10 이하의 자연수일 때 A = 10 이하의 소수 · B = 10보다 작은 3의 배수이다. 모두 넣으면 A^C · A - B · B - A 단추가 열려, 누를 때마다 그 조각이 노랗게 밝아지고 원소나열법이 함께 나타난다. ④성질 탐정 — 여섯 등식의 참·거짓을 가린다. A^C = U - A, (A - B) ∪ (A ∩ B) = A, A ∪ (B - A) = A ∪ B 는 참이고, A - B = B - A, A - B = A^C ∩ B, (A ∪ B)^C = A^C ∪ B^C 는 거짓이다. 맞히면 두 식의 조각을 겹쳐 그려 양쪽 모두에 있는 조각은 초록, 한쪽에만 있는 조각은 빨강으로 보여 주고 어긋나는 조각을 말로도 설명한다. 데이터는 node 로 전수 검산했다 — 식 30개가 나타내는 조각을, 조각마다 원소를 하나씩 두고 여집합·차집합까지 실제 집합 연산으로 계산해 대조했다. 탭①의 여섯 조각과 「앞에서 본 것과 같다」는 표시가 실제로 맞는지, A - B 와 B - A 가 정말 다른지 확인했고, 세 전체집합이 모두 A 를 담고 있으며 여집합이 서로 다르게 나오는지도 확인했다. 탭②는 좌우 조각이 일치하는지와 A ∩ A^C 가 빈 것 · A ∪ A^C 가 네 조각 전부인지를 확인했다. 탭③은 두 세트의 원소 배치에서 읽어 낸 A^C · A - B · B - A 를 정의 그대로 다시 계산해 대조했고, 조각마다 원소가 빠짐없이 한 번씩 들어가는지도 확인했다. 탭④는 네 조각을 모두 견주어 참·거짓과 어긋나는 조각을 대조했다(참 3 · 거짓 3). 네 조각의 원소 자리가 실제로 그 조각으로 판정되는지·U 상자를 벗어나지 않는지·칩끼리 겹치지 않는지, 두 원이 U 상자 안에서 겹치되 한쪽이 다른 쪽을 삼키지 않는지, 원과 U 의 이름표가 원 안으로 들어가지 않는지도 좌표로 전수 검사했다(처음 잡은 배치에서 조각 하나의 자리가 U 상자를 벗어나 도형 크기를 다시 잡았다). 활동에서 만들어지는 KaTeX 수식 64개도 모두 렌더해 오류가 없고 수식 안에 한글이 섞이지 않았음을 확인했다.$ov$, now()),
  ($s$common2/mini/de_morgan_lab$s$, $ov$드모르간의 법칙과 n(A ∪ B) 를 세는 여러 길을 네 탭으로 익히는 활동이다. 전체집합 U 안이 네 조각으로 나뉜 벤 다이어그램을 인라인 SVG 로 그렸고, 각 조각은 원 안쪽·바깥쪽 잘라내기를 겹쳐 만들어 눌리는 자리가 실제 조각 모양 그대로다. ①뒤집고 겹치기 — 같은 곳에 닿는 두 갈래 길을 손으로 걸어 본다. 왼쪽 길은 괄호 안(A ∪ B 또는 A ∩ B)을 칠한 뒤 「통째로 뒤집기」 단추를 눌러 여집합으로 바꾸고, 오른쪽 길은 A^C 와 B^C 를 각각 칠한 뒤 「겹치는 곳만 남기기」 또는 「둘을 합쳐 모으기」 단추로 이어 붙인다. 두 길이 같은 조각에 닿으면 등식이 열린다. 두 법칙을 모두 마치면 여집합 기호가 ∪ 를 ∩ 으로, ∩ 을 ∪ 으로 바꾼다는 정리와 집합이 n개일 때의 꼴이 함께 나온다. ②원소로 확인 — 구체적인 U, A, B 에서 좌변과 우변의 원소를 각각 골라 같은 집합임을 확인한다. 고른 원소는 맞으면 초록, 아니면 빨강으로 바로 표시되고, 「중간 단계 보기」를 누르면 A ∪ B(또는 A ∩ B)와 A^C · B^C 를 볼 수 있다. 네 문제는 9 이하의 자연수에서 6의 약수와 소수, 8 이하의 자연수에서 8의 약수와 짝수, 10 이하의 자연수에서 4 이상인 수와 10의 약수, 6 이하의 자연수에서 6의 약수와 짝수이며 두 법칙이 두 문제씩이다. ③개수 세는 길 — 세 조각의 개수 a, b, c 를 슬라이더로 정해 놓고 여덟 가지 식을 견준다. 식을 누르면 그 식이 세는 조각이 노랗게 밝아지고 값이 함께 표시되므로, 슬라이더를 움직이며 언제나 n(A ∪ B) 와 같은지 살핀 뒤 「언제나 같음 / 다를 수 있음」을 판정한다. 같은 것 다섯은 n(A∪B), n(A-B)+n(A∩B)+n(B-A), n(A)+n(B-A), n(A-B)+n(B), n(A)+n(B)-n(A∩B) 이고, 다른 것 셋은 겹치는 조각을 두 번 세는 n(A)+n(B), 겹치는 조각을 빠뜨리는 n(A-B)+n(B-A), 덜어 내지 않아도 될 것을 빼는 n(A∪B)-n(A∩B) 이다. ④조건과 포함관계 — 조건이 주어지면 먼저 「반드시 비어 있어야 하는 조각」을 눌러 찾고, 그다음 포함관계를 고른다. 맞히면 그 조각에 빨간 X 가 그려지고 중첩된 원 그림이 나타난다. 여섯 조건은 A ∪ B = A, A ∩ B = A, A - B = ∅, A^C ⊂ B^C, A ∩ B^C = ∅, A ∪ B^C = U 이며 A ⊂ B 와 B ⊂ A 가 세 문제씩이다. 데이터는 node 로 전수 검산했다 — 식 22개가 나타내는 조각을 실제 집합 연산으로 다시 계산해 대조했고, 「뒤집기」가 정말 여집합과 같은지, 두 조각을 이어 붙인 것이 오른쪽 식과 같은지, 안쪽 연산과 바깥 연산이 서로 바뀌는지를 확인했다. 탭②의 네 문제는 좌변과 우변을 각각 정의대로 계산해 서로 같음을 확인하고 조건제시법의 원소도 다시 계산해 대조했다. 탭③의 여덟 식은 (a, b, c) 가 0부터 9까지인 1,000가지 조합에서 값을 전수 대조해 「언제나 같은지」를 가렸고, 조각마다 원소를 실제로 만들어 n(A) · n(B) · n(A∩B) 세는 것도 무작위로 확인했다. 탭④는 조각을 지운 16가지 경우 모두에서 「조건이 성립한다」와 「그 조각이 비어 있다」가 동치인지, 그리고 포함관계 결론도 같은 방식으로 동치인지를 확인했다. 네 조각의 자리와 원 배치·이름표 자리도 좌표로 검사했으며, 활동에서 만들어지는 KaTeX 수식 91개를 모두 렌더해 오류가 없고 수식 안에 한글이 섞이지 않았음을 확인했다.$ov$, now())
